    public <T> CompletableFuture<T> async(java.util.concurrent.Callable<T> task) {
        CompletableFuture<T> future = new CompletableFuture<>();
        Runnable runner = () -> {
            try {
                future.complete(task.call());
            } catch (Exception e) {
                future.completeExceptionally(e);
            }
        };

        if (this.backendType() == PersistenceType.SQL) {
            this.sqlDatabase().getPool().execute(runner);
        } else {
            CompletableFuture.runAsync(runner);
        }
        return future;
    }

    /**
     * Runs a fire-and-forget task asynchronously.
     */
    public CompletableFuture<Void> asyncRun(Runnable task) {
        return async(() -> {
            task.run();
            return null;
        });
    }

    // -------------------------------------------------------------------------
    // Cache utilities
    // -------------------------------------------------------------------------

    /**
     * Populates {@code target} with every record of {@code entityClass} from the backend.
     * Useful inside adapter constructors or {@code onInit}.
     *
     * <pre>{@code
     * // inside SqlAdapter constructor
     * adapter.loadEntireData(repository.getProfileCache(), ProfileRecord.class);
     * }</pre>
     */
    public <K, V> void loadEntireData(Map<K, V> target, Class<V> entityClass) {
        EntityStore<V, K> store = getStore(entityClass);
        store.findAll().forEach(entity -> target.put(store.idOf(entity), entity));
    }

    /**
     * Flushes every entry in {@code source} back to the backend.
     */
    public <V> void flushEntireData(Map<?, V> source, Class<V> entityClass) {
        EntityStore<V, ?> store = getStore(entityClass);
        store.saveAll(source.values());
    }

    // -------------------------------------------------------------------------
    // Lifecycle
    // -------------------------------------------------------------------------

    /**
     * Persists all in-memory caches to the backend.
     * Called automatically via {@link #close()}; also safe to call manually for
     * periodic saves.
     */
    public abstract void saveAll();

    @Override
    public void close() {
        this.saveAll();
        super.close();
    }

    /** Compatibility shim for older call-sites. */
    @Deprecated(forRemoval = false)
    public PersistenceSession getSession() {
        return this;
    }

    public DatabaseAdapter<DatabaseRepository> getActiveAdapter() {
        ensureAdapterActivated();
        return activeAdapter;
    }

    // -------------------------------------------------------------------------
    // Internal
    // -------------------------------------------------------------------------

    private static final class DefaultJsonAdapter extends JsonAdapter<DatabaseRepository> {

        private DefaultJsonAdapter(DatabaseRepository repository) {
            super(repository);
        }
    }

    private static final class DefaultSqlAdapter extends SqlAdapter<DatabaseRepository> {

        private DefaultSqlAdapter(DatabaseRepository repository) {
            super(repository);
        }
    }

    private static final class DefaultMongoAdapter extends BackendAdapter<DatabaseRepository> {

        private DefaultMongoAdapter(DatabaseRepository repository) {
            super(repository);
        }
    }

    @SuppressWarnings("unchecked")
    private <T> EntityStore<T, Object> castStore(EntityStore<T, ?> store) {
    private static final class DefaultMongoAdapter extends MongoAdapter<DatabaseRepository> {
    }

    @SuppressWarnings("unchecked")
    private <T> EntityModel<T, Object> castModel(EntityModel<T, ?> model) {
        return (EntityModel<T, Object>) model;
    }

    private List<SortClause> resolveSorts(EntityModel<?, ?> model, String rankField, List<SortClause> explicit) {
        if (explicit != null && !explicit.isEmpty()) {
            return List.copyOf(explicit);
        }

        if (rankField != null && !rankField.isBlank()) {
            return model.rank(rankField)
                    .map(EntityModel.RankDef::sorts)
                    .orElseThrow(() -> new IllegalArgumentException(
                            "Unknown @PersistedRank field '" + rankField + "' for " + model.entityType().getSimpleName()
                    ));
        }

        if (model.ranks().size() == 1) {
            return model.ranks().get(0).sorts();
        }

        if (!model.ranks().isEmpty()) {
            throw new IllegalStateException("Multiple @PersistedRank fields found on " + model.entityType().getSimpleName() + ". Use rankField(...)");
        }

        return List.of(new SortClause(model.idColumn().name(), SortDirection.ASC));
    }

    private List<EntityModel.RankDef> resolveRankDefs(EntityModel<?, ?> model, Set<String> selectedRankFields) {
        if (model.ranks().isEmpty()) {
            return List.of();
        }
        if (selectedRankFields == null || selectedRankFields.isEmpty()) {
            return model.ranks();
        }

        List<EntityModel.RankDef> out = new ArrayList<>();
        for (String name : selectedRankFields) {
            EntityModel.RankDef def = model.rank(name)
                    .orElseThrow(() -> new IllegalArgumentException(
                            "Unknown @PersistedRank field '" + name + "' for " + model.entityType().getSimpleName()
                    ));
            out.add(def);
        }
        return out;
    }

    private static Class<?> inferIdType(Class<?> entityType) {
        for (Field f : entityType.getDeclaredFields()) {
            if (f.getAnnotation(PersistedId.class) != null) return f.getType();
        }
        throw new IllegalArgumentException("No @PersistedId field found in " + entityType.getName());
    }

    private <T> Comparator<T> buildMemoryComparator(Class<T> entityClass, List<SortClause> clauses) {
        Comparator<T> comparator = null;
        for (SortClause clause : clauses) {
            Field field = resolveSortField(entityClass, clause.field());
}
        }
        return out.toString();
    }

    @SuppressWarnings({"rawtypes", "unchecked"})
    private int compareFieldValues(Field field, Object left, Object right) {
        Object leftValue;
        Object rightValue;
        try {
            leftValue = field.get(left);
            rightValue = field.get(right);
        } catch (IllegalAccessException e) {
            throw new RuntimeException("Unable to read sort field '" + field.getName() + "'", e);
        }

        if (leftValue == rightValue) return 0;
        if (leftValue == null) return 1;
        if (rightValue == null) return -1;

        if (leftValue instanceof Comparable<?> && rightValue instanceof Comparable<?>) {
            return ((Comparable) leftValue).compareTo(rightValue);
        }
        return String.valueOf(leftValue).compareTo(String.valueOf(rightValue));
    }

    private <T> List<T> applyWindow(List<T> values, int offset, int limit) {
        if (offset >= values.size()) {
            return List.of();
        }
        int from = Math.max(0, offset);
        int to = limit < 0 ? values.size() : Math.min(values.size(), from + Math.max(0, limit));
        return new ArrayList<>(values.subList(from, to));
    }
}

package fr.ibrakash.helper.persistence.adapter;

import fr.ibrakash.helper.configuration.objects.database.ConfigPersistence;
import fr.ibrakash.helper.persistence.EntityStore;
import fr.ibrakash.helper.persistence.PersistenceSession;
import fr.ibrakash.helper.persistence.PersistenceType;
import fr.ibrakash.helper.persistence.entity.PersistedId;
import fr.ibrakash.helper.persistence.entity.internal.EntityModel;
import fr.ibrakash.helper.persistence.query.SortClause;
import fr.ibrakash.helper.persistence.query.SortDirection;
import fr.ibrakash.helper.persistence.query.SortQuery;
import fr.ibrakash.helper.platform.KashAddon;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Function;

/**
 * Base class for all data repositories.
 *
 * <p>A {@code DatabaseRepository} owns the in-memory caches, the persistence session,
 * and the selected {@link DatabaseAdapter}. Repositories may register custom adapters
 * for one or more backend types, but they can also rely entirely on the built-in
 * default adapters.
 *
 * <h2>Lifecycle</h2>
 * <ol>
 *   <li>Subclass constructor calls {@code super(addon, config)}</li>
 *   <li>Optionally register custom adapters via {@link #registerAdapter}</li>
 *   <li>Optionally call {@link #activateAdapter()} for eager warm-up</li>
 *   <li>Otherwise, the adapter is activated lazily on first persistence use</li>
 *   <li>On disable: call {@link #saveAll()} then {@link #close()}</li>
 * </ol>
 *
 * <h2>R/W helpers</h2>
 * <ul>
 *   <li>{@link #deserializeData(Class, Object)} - load one entity by id</li>
 *   <li>{@link #serializeData(Object, List, List)} - upsert one entity</li>
 *   <li>{@link #serializeBulkData(List, List, List)} - batch upsert</li>
 *   <li>{@link #deserializeBulkData(Class, List)} - batch load by ids</li>
 * </ul>
 *
 * <p>All entity stores are cached internally so {@link #getStore(Class)} always
 * returns the same instance.
 */
public abstract class DatabaseRepository extends PersistenceSession {

    private final Map<DatabaseAdapterType, Function<DatabaseRepository, DatabaseAdapter<DatabaseRepository>>> adapterFactories = new EnumMap<>(DatabaseAdapterType.class);
    private volatile DatabaseAdapter<DatabaseRepository> activeAdapter;
    private volatile boolean adapterActivating;

    // Internal entity-store cache: entityClass -> EntityStore
    private final Map<Class<?>, EntityStore<?, ?>> storeCache = new ConcurrentHashMap<>();
    private final Map<Class<?>, EntityModel<?, ?>> modelCache = new ConcurrentHashMap<>();
    private final Map<Class<?>, Map<String, Field>> sortFieldCache = new ConcurrentHashMap<>();

    /**
     * Creates the persistence session and prepares optional adapter registration.
     *
     * <p>Custom adapters can still be registered from the subclass constructor, but
     * repositories are no longer required to register or activate one manually:
     * the default backend adapter is resolved lazily on first persistence use.
     */
    @SuppressWarnings("unchecked")
    protected DatabaseRepository(KashAddon<?> addon, ConfigPersistence config) {
        super(addon, config);
    }

    // -------------------------------------------------------------------------
    // Adapter registration
    // -------------------------------------------------------------------------

    /**
     * Registers an adapter factory for the given backend type.
     * Call this from the subclass constructor before {@link #activateAdapter()}.
     *
     * @param type    backend type
     * @param factory a function that receives {@code this} and constructs the adapter
     * @param <R>     concrete repository type
     */
    @SuppressWarnings("unchecked")
    public <R extends DatabaseRepository> void registerAdapter(DatabaseAdapterType type, Function<R, DatabaseAdapter<R>> factory) {
        this.adapterFactories.put(type, (Function<DatabaseRepository, DatabaseAdapter<DatabaseRepository>>) (Function<?, ?>) factory);
    }

    /**
     * Selects and initialises the adapter matching the active backend.
     *
     * <p>If no custom adapter was registered for the current backend, a built-in
     * default adapter is created automatically. Calling this method is now optional:
     * it only forces early activation (useful for cache warm-up in custom adapters).
     */
    protected final void activateAdapter() {
        ensureAdapterActivated();
    }

    protected final void ensureAdapterActivated() {
        if (this.activeAdapter != null || this.adapterActivating) {
            return;
        }
        synchronized (this) {
            if (this.activeAdapter != null || this.adapterActivating) {
                return;
            }
            this.adapterActivating = true;
            try {
                DatabaseAdapterType adapterType = DatabaseAdapterType.from(this.backendType());
                Function<DatabaseRepository, DatabaseAdapter<DatabaseRepository>> factory = this.adapterFactories.get(adapterType);
                this.activeAdapter = factory != null ? factory.apply(this) : createDefaultAdapter(adapterType);
            } finally {
                this.adapterActivating = false;
            }
        }
    }

    private DatabaseAdapter<DatabaseRepository> createDefaultAdapter(DatabaseAdapterType type) {
        return switch (type) {
            case JSON -> new DefaultJsonAdapter(this);
            case SQL -> new DefaultSqlAdapter(this);
            case MONGO -> new DefaultMongoAdapter(this);
        };
    }

    // -------------------------------------------------------------------------
    // Entity store access
    // -------------------------------------------------------------------------

    /**
     * Returns (or creates) the {@link EntityStore} for the given entity class.
     * The id type is inferred from {@link PersistedId}.
     */
    @SuppressWarnings("unchecked")
    public <T, ID> EntityStore<T, ID> getStore(Class<T> entityClass) {
        ensureAdapterActivated();
        return (EntityStore<T, ID>) storeCache.computeIfAbsent(entityClass, c -> {
            Class<ID> idType = (Class<ID>) inferIdType(c);
            return this.entity(c, idType);
        });
    }

    /**
     * Returns (or creates) the {@link EntityStore} with an explicit id type.
     */
    @SuppressWarnings("unchecked")
    public <T, ID> EntityStore<T, ID> getStore(Class<T> entityClass, Class<ID> idType) {
        ensureAdapterActivated();
        return (EntityStore<T, ID>) storeCache.computeIfAbsent(entityClass, c -> this.entity(c, idType));
    }

    @SuppressWarnings("unchecked")
    protected <T, ID> EntityModel<T, ID> getModel(Class<T> entityClass) {
        return (EntityModel<T, ID>) this.modelCache.computeIfAbsent(entityClass, c -> {
            Class<ID> idType = (Class<ID>) inferIdType(c);
            return EntityModel.from(entityClass, idType);
        });
    }

    // -------------------------------------------------------------------------
    // R/W helpers — single
    // -------------------------------------------------------------------------

    /**
     * Loads one entity from the backend by id.
     *
     * <pre>{@code
     * ExampleData data = this.deserializeData(ExampleData.class, uuid);
     * }</pre>
     *
     * @param entityClass entity type
     * @param id          primary key value
     * @param <T>         entity type
     * @param <ID>        id type
     * @return the entity, or {@code null} if not found
     */
    @SuppressWarnings("unchecked")
    public <T, ID> T deserializeData(Class<T> entityClass, ID id) {
        EntityStore<T, ID> store = getStore(entityClass);
        return store.find(id).orElse(null);
    }

    /**
     * Loads one entity as an {@link Optional}.
     */
    public <T, ID> Optional<T> deserializeOptional(Class<T> entityClass, ID id) {
        EntityStore<T, ID> store = getStore(entityClass);
        return store.find(id);
    }

    /**
     * Upserts one entity to the backend.
     *
     * <p>The {@code keys} and {@code values} parameters exist for documentation /
     * explicitness purposes in the calling code — the actual persistence is driven
     * by the annotated entity fields via {@link EntityStore#save(Object)}.
     *
     * <pre>{@code
     * this.serializeData(data,
     *     List.of(data.getUUID()),
     *     List.of(data.getPoints(), data.getScore())
     * );
     * }</pre>
     *
     * @param entity the entity to save
     * @param keys   identifying values (e.g. primary key) — informational only
     * @param values non-key column values — informational only
     * @param <T>    entity type
     */
    @SuppressWarnings("unchecked")
    public <T> void serializeData(T entity, List<?> keys, List<?> values) {
        EntityStore<T, ?> store = (EntityStore<T, ?>) getStore(entity.getClass());
        store.save(entity);
    }

    // -------------------------------------------------------------------------
    // R/W helpers — bulk
    // -------------------------------------------------------------------------

    /**
     * Batch-upserts a list of entities.
     *
     * <p>{@code keyExtractors} and {@code valueExtractors} are provided for
     * explicitness in the caller and are not used for actual persistence.
     *
     * <pre>{@code
     * this.serializeBulkData(dataList,
     *     List.of(ExampleData::getUUID),
     *     List.of(ExampleData::getPoints, ExampleData::getScore)
     * );
     * }</pre>
     *
     * @param entities       list of entities to save
     * @param keyExtractors  functions that extract key fields — informational
     * @param valueExtractors functions that extract value fields — informational
     * @param <T>            entity type
     */
    @SuppressWarnings("unchecked")
    public <T> void serializeBulkData(List<T> entities,
                                      List<Function<T, ?>> keyExtractors,
                                      List<Function<T, ?>> valueExtractors) {
        if (entities.isEmpty()) return;
        Class<T> entityClass = (Class<T>) entities.get(0).getClass();
        EntityStore<T, ?> store = (EntityStore<T, ?>) getStore(entityClass);
        store.saveAll(entities);
    }

    /**
     * Batch-loads entities by a list of ids.
     *
     * <pre>{@code
     * List<ExampleData> loaded = this.deserializeBulkData(ExampleData.class, uuids);
     * }</pre>
     *
     * @param entityClass entity type
     * @param ids         list of primary key values to fetch
     * @param <T>         entity type
     * @param <ID>        id type
     * @return list of found entities (missing ids are silently skipped)
     */
    public <T, ID> List<T> deserializeBulkData(Class<T> entityClass, List<ID> ids) {
        EntityStore<T, ID> store = getStore(entityClass);
        return store.findAllByIds(ids);
    }

    /**
     * Batch-loads entities by ids — overload matching the {@code ExampleRepository}
     * signature where ids are wrapped inside a single-element outer list.
     */
    public <T, ID> List<T> deserializeBulkData(Class<T> entityClass,
                                                List<List<ID>> idLists,
                                                List<Function<T, ?>> valueExtractors) {
        List<ID> flat = new ArrayList<>();
        for (List<ID> chunk : idLists) flat.addAll(chunk);
        return deserializeBulkData(entityClass, flat);
    }

    // -------------------------------------------------------------------------
    // Sorted reads
    // -------------------------------------------------------------------------

    public <T> SortBuilder<T> sortBuilder(Class<T> entityClass) {
        return new SortBuilder<>(entityClass);
    }

    public <T> RankBuilder<T> rankBuilder(Class<T> entityClass) {
        return new RankBuilder<>(entityClass);
    }

    public <T> RankUpdater<T> rankUpdater(Class<T> entityClass) {
        return new RankUpdater<>(entityClass);
    }

    public <T> List<T> sortDeserializedProfiles(Class<T> entityClass,
                                                String sortField,
                                                SortDirection direction,
                                                int limit) {
        return this.sortBuilder(entityClass)
                .clause(sortField, direction)
                .limit(limit)
                .build();
    }

    public <T> List<T> sortDeserializedProfiles(Class<T> entityClass,
                                                List<SortClause> sorts,
                                                int limit) {
        SortBuilder<T> builder = this.sortBuilder(entityClass).limit(limit);
        for (SortClause sort : sorts) {
            builder.clause(sort.field(), sort.direction());
        }
        return builder.build();
    }

    public <T> List<T> sortDeserializedProfiles(Class<T> entityClass,
                                                Comparator<T> comparator) {
        return this.sortBuilder(entityClass)
                .memoryCache(getStore(entityClass).findAll())
                .comparator(comparator)
                .build();
    }

    public <T> List<T> sortDeserializedProfiles(Class<T> entityClass,
                                                Comparator<T> comparator,
                                                int limit) {
        return this.sortBuilder(entityClass)
                .memoryCache(getStore(entityClass).findAll())
                .comparator(comparator)
                .limit(limit)
                .build();
    }

    public <T> List<T> sortDeserializedProfiles(Class<T> entityClass,
                                                String sortField,
                                                SortDirection direction) {
        return sortDeserializedProfiles(entityClass, sortField, direction, -1);
    }

    public <T> List<T> sortDeserializedProfiles(Class<T> entityClass,
                                                List<SortClause> sorts) {
        return sortDeserializedProfiles(entityClass, sorts, -1);
    }

    public final class SortBuilder<T> {

        private final Class<T> entityClass;
        private final List<SortClause> clauses = new ArrayList<>();
        private int offset = 0;
        private int limit = -1;
        private final Set<String> columns = new LinkedHashSet<>();

        // memory-cache path
        private Collection<T> memoryCacheCollection;
        private Map<?, T> memoryCacheMap;
        private boolean reuseInstances = false;
        private Comparator<T> comparator;

        private SortBuilder(Class<T> entityClass) {
            this.entityClass = entityClass;
        }

        public SortBuilder<T> ascClause(String field) {
            this.clauses.add(SortClause.asc(field));
            return this;
        }

        public SortBuilder<T> descClause(String field) {
            this.clauses.add(SortClause.desc(field));
            return this;
        }

        public SortBuilder<T> clause(String field, SortDirection direction) {
            this.clauses.add(new SortClause(field, direction));
            return this;
        }

        /** Start at row {@code offset} (0-based). */
        public SortBuilder<T> offset(int offset) {
            this.offset = Math.max(0, offset);
            return this;
        }

        public SortBuilder<T> limit(int limit) {
            this.limit = limit;
            return this;
        }

        /** Convenience: page from start index with page size. */
        public SortBuilder<T> window(int offset, int limit) {
            this.offset = Math.max(0, offset);
            this.limit = limit;
            return this;
        }

        /**
         * Restrict SQL SELECT to these columns only (id always included).
         * Ignored when memoryCache is provided.
         */
        public SortBuilder<T> loadColumns(String... fields) {
            this.columns.addAll(List.of(fields));
            return this;
        }

        /** Full column load — explicit no-op, here for readability. */
        public SortBuilder<T> loadFullColumns() {
            this.columns.clear();
            return this;
        }

        /** Sort a pre-loaded Collection without hitting the backend. */
        public SortBuilder<T> memoryCache(Collection<T> cacheValues) {
            this.memoryCacheCollection = cacheValues;
            this.memoryCacheMap = null;
            return this;
        }

        /**
         * Sort using a Map cache.
         *
         * @param cacheMap       the live map (String/ID key → entity)
         * @param reuseInstances if {@code true}, merge fresh DB values into existing
         *                       instances (keeps same object references); if
         *                       {@code false}, replace entries with new instances.
         *                       Ignored when no backend fetch is triggered.
         */
        public <K> SortBuilder<T> memoryCache(Map<K, T> cacheMap, boolean reuseInstances) {
            this.memoryCacheMap = cacheMap;
            this.memoryCacheCollection = null;
            this.reuseInstances = reuseInstances;
            return this;
        }

        /** Convenience — {@code memoryCache(map, false)}. */
        public <K> SortBuilder<T> memoryCache(Map<K, T> cacheMap) {
            return memoryCache(cacheMap, false);
        }

        public SortBuilder<T> comparator(Comparator<T> comparator) {
            this.comparator = comparator;
            return this;
        }

        public List<T> build() {
            return build(Function.identity());
        }

        public <R> List<R> build(Function<T, R> mapper) {
            List<T> sorted = executeSorted();
            if (mapper == Function.identity()) {
                @SuppressWarnings("unchecked")
                List<R> result = (List<R>) sorted;
                return result;
            }
            List<R> out = new ArrayList<>(sorted.size());
            for (T item : sorted) {
                out.add(mapper.apply(item));
            }
            return out;
        }

        private List<T> executeSorted() {
            if (this.memoryCacheCollection != null) {
                return sortInMemory(new ArrayList<>(this.memoryCacheCollection));
            }

            if (this.memoryCacheMap != null) {
                return sortInMemory(new ArrayList<>(this.memoryCacheMap.values()));
            }

            EntityStore<T, ?> store = getStore(this.entityClass);
            SortQuery query = new SortQuery(List.copyOf(this.clauses), this.offset, this.limit, Set.copyOf(this.columns));
            return store.findAllSorted(query);
        }

        private List<T> sortInMemory(List<T> out) {
            if (this.comparator != null) {
                out.sort(this.comparator);
            } else if (!this.clauses.isEmpty()) {
                out.sort(buildMemoryComparator(this.entityClass, this.clauses));
            }
            return applyWindow(out, this.offset, this.limit);
        }
    }

    public final class RankBuilder<T> {

        private final Class<T> entityClass;
        private final List<SortClause> clauses = new ArrayList<>();
        private T data;
        private String rankField;

        private RankBuilder(Class<T> entityClass) {
            this.entityClass = entityClass;
        }

        public RankBuilder<T> data(T data) {
            this.data = data;
            return this;
        }

        public RankBuilder<T> rankField(String rankField) {
            this.rankField = rankField;
            return this;
        }

        public RankBuilder<T> ascClause(String field) {
            this.clauses.add(SortClause.asc(field));
            return this;
        }

        public RankBuilder<T> descClause(String field) {
            this.clauses.add(SortClause.desc(field));
            return this;
        }

        public RankBuilder<T> clause(String field, SortDirection direction) {
            this.clauses.add(new SortClause(field, direction));
            return this;
        }

        public int build() {
            if (this.data == null) {
                throw new IllegalStateException("rankBuilder requires data(entity)");
            }

            EntityStore<T, Object> store = castStore(getStore(this.entityClass));
            EntityModel<T, Object> model = castModel(getModel(this.entityClass));
            Object id = store.idOf(this.data);
            List<SortClause> sorts = resolveSorts(model, this.rankField, this.clauses);
            return store.rankOf(id, sorts);
        }
    }

    public final class RankUpdater<T> {

        private final Class<T> entityClass;
        private final List<T> dataCollection = new ArrayList<>();
        private final Set<String> rankFields = new LinkedHashSet<>();

        private RankUpdater(Class<T> entityClass) {
            this.entityClass = entityClass;
        }

        public RankUpdater<T> data(T data) {
            if (data != null) this.dataCollection.add(data);
            return this;
        }

        public RankUpdater<T> dataCollection(Collection<T> dataCollection) {
            if (dataCollection != null) this.dataCollection.addAll(dataCollection);
            return this;
        }

        public RankUpdater<T> filteringRanks(String... rankNames) {
            if (rankNames != null) this.rankFields.addAll(List.of(rankNames));
            return this;
        }

        public RankUpdater<T> filtering_ranks(String... rankNames) {
            return filteringRanks(rankNames);
        }

        public void update() {
            if (this.dataCollection.isEmpty()) return;

            EntityStore<T, Object> store = castStore(getStore(this.entityClass));
            EntityModel<T, Object> model = castModel(getModel(this.entityClass));
            List<EntityModel.RankDef> defs = resolveRankDefs(model, this.rankFields);
            if (defs.isEmpty()) return;

            List<Object> ids = new ArrayList<>(this.dataCollection.size());
            Map<Object, T> byId = new HashMap<>(this.dataCollection.size());
            for (T data : this.dataCollection) {
                Object id = store.idOf(data);
                ids.add(id);
                byId.put(id, data);
            }

            for (EntityModel.RankDef def : defs) {
                Map<Object, Integer> ranks = store.ranksOf(ids, def.sorts());
                for (Map.Entry<Object, T> entry : byId.entrySet()) {
                    int rankValue = ranks.getOrDefault(entry.getKey(), -1);
                    model.writeRankValue(entry.getValue(), def, rankValue);
                }
            }
        }
    }

    // -------------------------------------------------------------------------
    // Builder APIs (compat)
    // -------------------------------------------------------------------------

    public <T> SerializerBuilder<T> serializer(Class<T> entityClass) {
        return new SerializerBuilder<>(entityClass);
    }

    public <ID, T> DeserializerBuilder<ID, T> deserializer(Class<ID> idType, Class<T> entityClass) {
        return new DeserializerBuilder<>(idType, entityClass);
    }

    public final class SerializerBuilder<T> {

        private final Class<T> entityClass;
        private final List<T> datas = new ArrayList<>();
        private final Set<String> columnFilters = new LinkedHashSet<>();

        private SerializerBuilder(Class<T> entityClass) {
            this.entityClass = entityClass;
        }

        public SerializerBuilder<T> data(T data) {
            if (data != null) this.datas.add(data);
            return this;
        }

        public SerializerBuilder<T> datas(List<T> datas) {
            if (datas != null) this.datas.addAll(datas);
            return this;
        }

        public SerializerBuilder<T> columnFilters(String... columns) {
            if (columns != null) this.columnFilters.addAll(List.of(columns));
            return this;
        }

        public List<Integer> flush() {
            if (this.datas.isEmpty()) return List.of();
            EntityStore<T, ?> store = getStore(this.entityClass);
            Set<String> selected = this.columnFilters.isEmpty() ? Set.of() : Set.copyOf(this.columnFilters);
            store.saveAll(this.datas, selected);
            return this.datas.stream().map(x -> 1).toList();
        }
    }

    public final class DeserializerBuilder<ID, T> {

        private final Class<ID> idType;
        private final Class<T> entityClass;
        private final List<ID> ids = new ArrayList<>();
        private final Set<String> columnFilters = new LinkedHashSet<>();

        // Optional source/context pipeline.
        private Map<ID, ?> contextMap;
        private BiConsumer<T, Object> onFoundWithContext;
        private Function<Object, T> onMissingFactory;

        private DeserializerBuilder(Class<ID> idType, Class<T> entityClass) {
            this.idType = idType;
            this.entityClass = entityClass;
        }

        public DeserializerBuilder<ID, T> id(ID id) {
            if (id != null) this.ids.add(id);
            return this;
        }

        public DeserializerBuilder<ID, T> ids(List<ID> ids) {
            if (ids != null) this.ids.addAll(ids);
            return this;
        }

        public DeserializerBuilder<ID, T> columnFilters(String... columns) {
            if (columns != null) this.columnFilters.addAll(List.of(columns));
            return this;
        }

        public <S> SourceDeserializerBuilder<S> from(Collection<S> source, Function<S, ID> idExtractor) {
            Map<ID, S> map = new HashMap<>();
            if (source != null && idExtractor != null) {
                for (S value : source) {
                    if (value == null) continue;
                    ID extracted = idExtractor.apply(value);
                    if (extracted == null) continue;
                    map.put(extracted, value);
                }
            }
            this.contextMap = map;
            this.ids.clear();
            this.ids.addAll(map.keySet());
            return new SourceDeserializerBuilder<>();
        }

        @SuppressWarnings("unchecked")
        public <S> DeserializerBuilder<ID, T> onFound(BiConsumer<T, S> binder) {
            if (binder == null) {
                this.onFoundWithContext = null;
                return this;
            }
            this.onFoundWithContext = (data, ctx) -> binder.accept(data, (S) ctx);
            return this;
        }

        @SuppressWarnings("unchecked")
        public <S> DeserializerBuilder<ID, T> onMissing(Function<S, T> factory) {
            if (factory == null) {
                this.onMissingFactory = null;
                return this;
            }
            this.onMissingFactory = ctx -> factory.apply((S) ctx);
            return this;
        }

        public List<T> build() {
            return build(Function.identity());
        }

        public <R> List<R> build(Function<T, R> mapper) {
            if (this.ids.isEmpty()) return List.of();
            List<R> out = new ArrayList<>(this.ids.size());
            load(entity -> out.add(mapper.apply(entity)));
            return out;
        }

        public <K> Map<K, T> toMap(Function<T, K> keyMapper) {
            Map<K, T> out = new HashMap<>();
            load(entity -> out.put(keyMapper.apply(entity), entity));
            return out;
        }

        public void load(Consumer<T> consumer) {
            if (this.ids.isEmpty()) return;

            EntityStore<T, ID> store = getStore(this.entityClass, this.idType);
            Set<String> selected = this.columnFilters.isEmpty() ? Set.of() : Set.copyOf(this.columnFilters);

            if (this.contextMap == null) {
                store.findAllByIds(this.ids, selected, consumer);
                return;
            }

            Set<ID> found = new LinkedHashSet<>();
            store.findAllByIds(this.ids, selected, loaded -> {
                ID loadedId = store.idOf(loaded);
                found.add(loadedId);
                Object ctx = this.contextMap.get(loadedId);
                if (ctx != null && this.onFoundWithContext != null) {
                    this.onFoundWithContext.accept(loaded, ctx);
                }
                consumer.accept(loaded);
            });

            if (this.onMissingFactory == null) {
                return;
            }

            for (ID id : this.ids) {
                if (found.contains(id)) continue;
                Object ctx = this.contextMap.get(id);
                if (ctx == null) continue;
                T created = this.onMissingFactory.apply(ctx);
                if (created == null) continue;
                if (this.onFoundWithContext != null) {
                    this.onFoundWithContext.accept(created, ctx);
                }
                consumer.accept(created);
            }
        }

        public final class SourceDeserializerBuilder<S> {

            private SourceDeserializerBuilder() {
            }

            public SourceDeserializerBuilder<S> columnFilters(String... columns) {
                DeserializerBuilder.this.columnFilters(columns);
                return this;
            }

            public SourceDeserializerBuilder<S> onFound(BiConsumer<T, S> binder) {
                DeserializerBuilder.this.onFound(binder);
                return this;
            }

            public SourceDeserializerBuilder<S> onMissing(Function<S, T> factory) {
                DeserializerBuilder.this.onMissing(factory);
                return this;
            }

            public List<T> build() {
                return DeserializerBuilder.this.build();
            }

            public <R> List<R> build(Function<T, R> mapper) {
                return DeserializerBuilder.this.build(mapper);
            }

            public <K> Map<K, T> toMap(Function<T, K> keyMapper) {
                return DeserializerBuilder.this.toMap(keyMapper);
            }

            public void load(Consumer<T> consumer) {
                DeserializerBuilder.this.load(consumer);
            }

            public DeserializerBuilder<ID, T> end() {
                return DeserializerBuilder.this;
            }
        }
    }

    // -------------------------------------------------------------------------
    // Async helpers
    // -------------------------------------------------------------------------

    /**
     * Wraps a blocking call in a {@link CompletableFuture} running on the
     * SQL thread-pool (if SQL) or the common fork-join pool otherwise.
     */
    public <T> CompletableFuture<T> async(java.util.concurrent.Callable<T> task) {
        CompletableFuture<T> future = new CompletableFuture<>();
        Runnable runner = () -> {
            try {
                future.complete(task.call());
            } catch (Exception e) {
                future.completeExceptionally(e);
            }
        };

        if (this.backendType() == PersistenceType.SQL) {
            this.sqlDatabase().getPool().execute(runner);
        } else {
            CompletableFuture.runAsync(runner);
        }
        return future;
    }

    /**
     * Runs a fire-and-forget task asynchronously.
     */
    public CompletableFuture<Void> asyncRun(Runnable task) {
        return async(() -> {
            task.run();
            return null;
        });
    }

    // -------------------------------------------------------------------------
    // Cache utilities
    // -------------------------------------------------------------------------

    /**
     * Populates {@code target} with every record of {@code entityClass} from the backend.
     * Useful inside adapter constructors or {@code onInit}.
     *
     * <pre>{@code
     * // inside SqlAdapter constructor
     * adapter.loadEntireData(repository.getProfileCache(), ProfileRecord.class);
     * }</pre>
     */
    public <K, V> void loadEntireData(Map<K, V> target, Class<V> entityClass) {
        EntityStore<V, K> store = getStore(entityClass);
        store.findAll().forEach(entity -> target.put(store.idOf(entity), entity));
    }

    /**
     * Flushes every entry in {@code source} back to the backend.
     */
    public <V> void flushEntireData(Map<?, V> source, Class<V> entityClass) {
        EntityStore<V, ?> store = getStore(entityClass);
        store.saveAll(source.values());
    }

    // -------------------------------------------------------------------------
    // Lifecycle
    // -------------------------------------------------------------------------

    /**
     * Persists all in-memory caches to the backend.
     * Called automatically via {@link #close()}; also safe to call manually for
     * periodic saves.
     */
    public abstract void saveAll();

    @Override
    public void close() {
        this.saveAll();
        super.close();
    }

    /** Compatibility shim for older call-sites. */
    @Deprecated(forRemoval = false)
    public PersistenceSession getSession() {
        return this;
    }

    public DatabaseAdapter<DatabaseRepository> getActiveAdapter() {
        ensureAdapterActivated();
        return activeAdapter;
    }

    // -------------------------------------------------------------------------
    // Internal
    // -------------------------------------------------------------------------

    private static final class DefaultJsonAdapter extends JsonAdapter<DatabaseRepository> {

        private DefaultJsonAdapter(DatabaseRepository repository) {
            super(repository);
        }
    }

    private static final class DefaultSqlAdapter extends SqlAdapter<DatabaseRepository> {

        private DefaultSqlAdapter(DatabaseRepository repository) {
            super(repository);
        }
    }

    private static final class DefaultMongoAdapter extends BackendAdapter<DatabaseRepository> {

        private DefaultMongoAdapter(DatabaseRepository repository) {
            super(repository);
        }
    }

    @SuppressWarnings("unchecked")
    private <T> EntityStore<T, Object> castStore(EntityStore<T, ?> store) {
        return (EntityStore<T, Object>) store;
    }

    @SuppressWarnings("unchecked")
    private <T> EntityModel<T, Object> castModel(EntityModel<T, ?> model) {
        return (EntityModel<T, Object>) model;
    }

    private List<SortClause> resolveSorts(EntityModel<?, ?> model, String rankField, List<SortClause> explicit) {
        if (explicit != null && !explicit.isEmpty()) {
            return List.copyOf(explicit);
        }

        if (rankField != null && !rankField.isBlank()) {
            return model.rank(rankField)
                    .map(EntityModel.RankDef::sorts)
                    .orElseThrow(() -> new IllegalArgumentException(
                            "Unknown @PersistedRank field '" + rankField + "' for " + model.entityType().getSimpleName()
                    ));
        }

        if (model.ranks().size() == 1) {
            return model.ranks().get(0).sorts();
        }

        if (!model.ranks().isEmpty()) {
            throw new IllegalStateException("Multiple @PersistedRank fields found on " + model.entityType().getSimpleName() + ". Use rankField(...)");
        }

        return List.of(new SortClause(model.idColumn().name(), SortDirection.ASC));
    }

    private List<EntityModel.RankDef> resolveRankDefs(EntityModel<?, ?> model, Set<String> selectedRankFields) {
        if (model.ranks().isEmpty()) {
            return List.of();
        }
        if (selectedRankFields == null || selectedRankFields.isEmpty()) {
            return model.ranks();
        }

        List<EntityModel.RankDef> out = new ArrayList<>();
        for (String name : selectedRankFields) {
            EntityModel.RankDef def = model.rank(name)
                    .orElseThrow(() -> new IllegalArgumentException(
                            "Unknown @PersistedRank field '" + name + "' for " + model.entityType().getSimpleName()
                    ));
            out.add(def);
        }
        return out;
    }

    private static Class<?> inferIdType(Class<?> entityType) {
        for (Field f : entityType.getDeclaredFields()) {
            if (f.getAnnotation(PersistedId.class) != null) return f.getType();
        }
        throw new IllegalArgumentException("No @PersistedId field found in " + entityType.getName());
    }

    private <T> Comparator<T> buildMemoryComparator(Class<T> entityClass, List<SortClause> clauses) {
        Comparator<T> comparator = null;
        for (SortClause clause : clauses) {
            Field field = resolveSortField(entityClass, clause.field());
            Comparator<T> fieldComparator = (left, right) -> compareFieldValues(field, left, right);
            if (clause.direction() == SortDirection.DESC) {
                fieldComparator = fieldComparator.reversed();
            }
            comparator = comparator == null ? fieldComparator : comparator.thenComparing(fieldComparator);
        }
        return comparator == null ? (left, right) -> 0 : comparator;
    }

    private Field resolveSortField(Class<?> entityClass, String fieldName) {
        Map<String, Field> byName = this.sortFieldCache.computeIfAbsent(entityClass, this::buildSortFieldMap);
        Field resolved = byName.get(fieldName.toLowerCase());
        if (resolved == null) {
            throw new IllegalArgumentException("Unknown memory sort field '" + fieldName + "' for " + entityClass.getSimpleName());
        }
        return resolved;
    }

    private Map<String, Field> buildSortFieldMap(Class<?> entityClass) {
        Map<String, Field> fields = new HashMap<>();
        Class<?> cursor = entityClass;
        while (cursor != null && cursor != Object.class) {
            for (Field field : cursor.getDeclaredFields()) {
                field.setAccessible(true);
                String plain = field.getName().toLowerCase();
                String snake = toSnake(field.getName());
                fields.putIfAbsent(plain, field);
                fields.putIfAbsent(snake, field);
            }
            cursor = cursor.getSuperclass();
        }
        return fields;
    }

    private static String toSnake(String input) {
        StringBuilder out = new StringBuilder(input.length() + 4);
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (Character.isUpperCase(c) && i > 0) {
                out.append('_');
            }
            out.append(Character.toLowerCase(c));
        }
        return out.toString();
    }

    @SuppressWarnings({"rawtypes", "unchecked"})
    private int compareFieldValues(Field field, Object left, Object right) {
        Object leftValue;
        Object rightValue;
        try {
            leftValue = field.get(left);
            rightValue = field.get(right);
        } catch (IllegalAccessException e) {
            throw new RuntimeException("Unable to read sort field '" + field.getName() + "'", e);
        }

        if (leftValue == rightValue) return 0;
        if (leftValue == null) return 1;
        if (rightValue == null) return -1;

        if (leftValue instanceof Comparable<?> && rightValue instanceof Comparable<?>) {
            return ((Comparable) leftValue).compareTo(rightValue);
        }
        return String.valueOf(leftValue).compareTo(String.valueOf(rightValue));
    }

    private <T> List<T> applyWindow(List<T> values, int offset, int limit) {
        if (offset >= values.size()) {
            return List.of();
        }
        int from = Math.max(0, offset);
        int to = limit < 0 ? values.size() : Math.min(values.size(), from + Math.max(0, limit));
        return new ArrayList<>(values.subList(from, to));
    }
}

package fr.ibrakash.helper.persistence.adapter;

import com.zaxxer.hikari.HikariDataSource;
import fr.ibrakash.helper.sql.SqlConsumer;
import fr.ibrakash.helper.sql.SqlDatabase;
import fr.ibrakash.helper.sql.SqlDriverType;
import fr.ibrakash.helper.sql.SqlResultStatement;
import fr.ibrakash.helper.sql.SqlStatement;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;

/**
 * Common SQL operation mixin for adapters.
 *
 * <p>Implementors only need to provide {@link #repository()}.
 */
public interface SqlAdapterOperations {

    DatabaseRepository repository();

    default SqlDatabase sqlDatabase() {
        return repository().sqlDatabase();
    }

    default SqlDriverType sqlDriver() {
        return repository().sqlDriver();
    }

    default ExecutorService sqlPool() {
        return sqlDatabase().getPool();
    }

    default HikariDataSource sqlDataSource() {
        return sqlDatabase().getDataSource();
    }

    default void openConnection(SqlConsumer<Connection> consumer) {
        sqlDatabase().openConnection(consumer);
    }

    default void execute(SqlStatement<Statement> consumer) {
        sqlDatabase().createClosingStatement(consumer);
    }

    default void prepare(String sql, SqlStatement<PreparedStatement> consumer) {
        sqlDatabase().prepareClosingStatement(sql, consumer);
    }

    default <V> V query(SqlResultStatement<Statement, V> consumer) {
        return sqlDatabase().resultStatement(consumer);
    }

    default <V> V query(String sql, SqlResultStatement<PreparedStatement, V> consumer) {
        return sqlDatabase().resultPreparedStatement(sql, consumer);
    }

    default void submitExecute(SqlStatement<Statement> consumer) {
        sqlDatabase().submitStatement(consumer);
    }

    default void submitPrepare(String sql, SqlStatement<PreparedStatement> consumer) {
        sqlDatabase().submitPreparedStatement(sql, consumer);
    }

    default <V> CompletableFuture<V> submitQuery(SqlResultStatement<Statement, V> consumer) {
        return sqlDatabase().submitResultStatement(consumer);
    }

    default <V> CompletableFuture<V> submitQuery(String sql, SqlResultStatement<PreparedStatement, V> consumer) {
        return sqlDatabase().submitPreparedResult(sql, consumer);
    }
}

package fr.ibrakash.helper.persistence.adapter;

import fr.ibrakash.helper.sql.SqlConsumer;
import fr.ibrakash.helper.sql.SqlDatabase;
import fr.ibrakash.helper.sql.SqlDriverType;
import fr.ibrakash.helper.sql.SqlResultStatement;
import fr.ibrakash.helper.sql.SqlStatement;

import javax.sql.DataSource;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;

/**
 * Common SQL operation mixin for adapters.
 *
 * <p>Implementors only need to provide {@link #repository()}.
 */
public interface SqlAdapterOperations {

    DatabaseRepository repository();

    default SqlDatabase sqlDatabase() {
        return repository().sqlDatabase();
    }

    default SqlDriverType sqlDriver() {
        return repository().sqlDriver();
    }

    default ExecutorService sqlPool() {
        return sqlDatabase().getPool();
    }

    default DataSource sqlDataSource() {
        return sqlDatabase().getDataSource();
    }

    default void openConnection(SqlConsumer<Connection> consumer) {
        sqlDatabase().openConnection(consumer);
    }

    default void execute(SqlStatement<Statement> consumer) {
        sqlDatabase().createClosingStatement(consumer);
    }

    default void prepare(String sql, SqlStatement<PreparedStatement> consumer) {
        sqlDatabase().prepareClosingStatement(sql, consumer);
    }

    default <V> V query(SqlResultStatement<Statement, V> consumer) {
        return sqlDatabase().resultStatement(consumer);
    }

    default <V> V query(String sql, SqlResultStatement<PreparedStatement, V> consumer) {
        return sqlDatabase().resultPreparedStatement(sql, consumer);
    }

    default void submitExecute(SqlStatement<Statement> consumer) {
        sqlDatabase().submitStatement(consumer);
    }

    default void submitPrepare(String sql, SqlStatement<PreparedStatement> consumer) {
        sqlDatabase().submitPreparedStatement(sql, consumer);
    }

    default <V> CompletableFuture<V> submitQuery(SqlResultStatement<Statement, V> consumer) {
        return sqlDatabase().submitResultStatement(consumer);
    }

    default <V> CompletableFuture<V> submitQuery(String sql, SqlResultStatement<PreparedStatement, V> consumer) {
        return sqlDatabase().submitPreparedResult(sql, consumer);
    }
}

package fr.ibrakash.helper.persistence.entity.internal;

import fr.ibrakash.helper.persistence.entity.NoPersistedBlobSerializer;
import fr.ibrakash.helper.persistence.entity.PersistedBlob;
import fr.ibrakash.helper.persistence.entity.PersistedBlobKind;
import fr.ibrakash.helper.persistence.entity.PersistedBlobSerializer;
import fr.ibrakash.helper.persistence.entity.PersistedBlobTier;
import fr.ibrakash.helper.persistence.entity.PersistedColumn;
import fr.ibrakash.helper.persistence.entity.PersistedEmbedded;
import fr.ibrakash.helper.persistence.entity.PersistedEntity;
import fr.ibrakash.helper.persistence.entity.PersistedId;
import fr.ibrakash.helper.persistence.entity.PersistedIndex;
import fr.ibrakash.helper.persistence.entity.PersistedIndexes;
import fr.ibrakash.helper.persistence.entity.PersistedRelation;
import fr.ibrakash.helper.persistence.entity.PersistedJson;
import fr.ibrakash.helper.persistence.entity.PersistedJsonMode;
import fr.ibrakash.helper.persistence.entity.PersistedRank;
import fr.ibrakash.helper.persistence.query.SortClause;
import fr.ibrakash.helper.persistence.query.SortDirection;

import java.lang.invoke.MethodHandles;
import java.lang.invoke.VarHandle;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Optional;

public final class EntityModel<T, ID> {

    private static final int MAX_INDEX_NAME_LENGTH = 63;

    public record Column(
            Field rootField,
            Field leafField,
            String name,
            Class<?> type,
            boolean nullable,
            String defaultValue,
            int length,
            boolean id,
            VarHandle rootHandle,
            VarHandle leafHandle,
            Constructor<?> rootConstructor
    ) {}

    public record IndexDef(String name, List<String> columns, boolean unique) {}

    public record RelationColumn(Field field, String name, Class<?> type, int length, VarHandle handle) {}

    public record RelationDef(
            Field field,
            VarHandle collectionHandle,
            Constructor<?> elementConstructor,
            String table,
            String joinColumn,
            String valueColumn,
            String orderColumn,
            Class<?> elementType,
            boolean simple,
            List<RelationColumn> objectColumns
    ) {}

    public record BlobDef(
            Field field,
            VarHandle handle,
            String name,
            Class<?> type,
            boolean nullable,
            PersistedBlobKind kind,
            PersistedBlobTier tier,
            int length,
            Class<? extends PersistedBlobSerializer<?>> serializerClass,
            PersistedBlobSerializer<Object> serializer,
            Constructor<?> binaryStorageConstructor
    ) {}

    public record RankDef(
            Field field,
            VarHandle handle,
            String name,
            List<SortClause> sorts,
            boolean loadOnDeserialize
    ) {}

    private final Class<T> entityType;
    private final Class<ID> idType;
    private final String namespace;
    private final Column idColumn;
    private final List<Column> columns;
    private final List<IndexDef> indexes;
    private final List<RelationDef> relations;
    private final List<BlobDef> blobs;
    private final Constructor<T> entityConstructor;
    private final PersistedJsonMode jsonMode;
    private final List<RankDef> ranks;

    private EntityModel(Class<T> entityType,
                        Class<ID> idType,
                        String namespace,
                        Column idColumn,
                        List<Column> columns,
                        List<IndexDef> indexes,
                        List<RelationDef> relations,
                        List<BlobDef> blobs,
                        Constructor<T> entityConstructor,
                        PersistedJsonMode jsonMode,
                        List<RankDef> ranks) {
        this.entityType = entityType;
        this.idType = idType;
        this.namespace = namespace;
        this.idColumn = idColumn;
        this.columns = columns;
        this.indexes = indexes;
        this.relations = relations;
        this.blobs = blobs;
        this.entityConstructor = entityConstructor;
        this.jsonMode = jsonMode;
        this.ranks = ranks;
    }

    public static <T, ID> EntityModel<T, ID> from(Class<T> entityType, Class<ID> idType) {
        Field idField = null;
        List<Column> cols = new ArrayList<>();
        List<RelationDef> relations = new ArrayList<>();
        List<BlobDef> blobs = new ArrayList<>();
        List<RankDef> ranks = new ArrayList<>();

        for (Field field : entityType.getDeclaredFields()) {
            field.setAccessible(true);

            PersistedId id = field.getAnnotation(PersistedId.class);
            PersistedRelation relation = field.getAnnotation(PersistedRelation.class);
            PersistedEmbedded embedded = field.getAnnotation(PersistedEmbedded.class);
            PersistedColumn col = field.getAnnotation(PersistedColumn.class);
            PersistedBlob blob = field.getAnnotation(PersistedBlob.class);
            PersistedRank rank = field.getAnnotation(PersistedRank.class);

            if (id != null) {
                if (idField != null) {
                    throw new IllegalArgumentException("Multiple @PersistedId fields in " + entityType.getName());
                }
                String name = id.value().isBlank() ? snake(field.getName()) : id.value();
                idField = field;
                cols.add(new Column(null, field, name, field.getType(), false, "", 36, true,
                        null, varHandle(field), null));
                continue;
            }

            if (relation != null) {
                continue;
            }

            if (rank != null) {
                int mod = field.getModifiers();
                if (!java.lang.reflect.Modifier.isTransient(mod)) {
                    throw new IllegalArgumentException("@PersistedRank field must be transient: " + entityType.getName() + "#" + field.getName());
                }
                ranks.add(new RankDef(field, varHandle(field), field.getName(), List.of(), rank.load_on_deserialize()));
                continue;
            }

            if (embedded != null) {
                cols.addAll(parseEmbedded(field, embedded));
                continue;
            }

            if (blob != null) {
                blobs.add(parseBlob(field, blob));
                continue;
            }

            if (col == null) {
                int mod = field.getModifiers();
                if (java.lang.reflect.Modifier.isStatic(mod) || java.lang.reflect.Modifier.isTransient(mod) || field.isSynthetic()) {
                    continue;
                }
                cols.add(new Column(null, field, snake(field.getName()), field.getType(), true, "", 255, false,
                        null, varHandle(field), null));
            } else {
                String name = col.value().isBlank() ? snake(field.getName()) : col.value();
                cols.add(new Column(null, field, name, field.getType(), col.nullable(), col.defaultValue(), col.length(), false,
                        null, varHandle(field), null));
            }
        }

        if (idField == null) {
            throw new IllegalArgumentException("Missing @PersistedId field in " + entityType.getName());
        }

        for (Field field : entityType.getDeclaredFields()) {
            PersistedRelation relation = field.getAnnotation(PersistedRelation.class);
            if (relation == null) continue;
            field.setAccessible(true);
            relations.add(parseRelation(field, relation, idField));
        }

        Column idCol = cols.stream().filter(Column::id).findFirst().orElseThrow();
        List<Column> nonId = cols.stream().filter(c -> !c.id()).toList();

        PersistedEntity entityAnn = entityType.getAnnotation(PersistedEntity.class);
        String namespace = entityAnn != null && !entityAnn.value().isBlank()
                ? entityAnn.value()
                : snake(entityType.getSimpleName());

        List<IndexDef> indexes = parseIndexes(entityType);

        List<SortClause> defaultSort = List.of(new SortClause(idCol.name(), SortDirection.ASC));
        List<RankDef> resolvedRanks = new ArrayList<>(ranks.size());
        for (RankDef rank : ranks) {
            PersistedRank ann = rank.field().getAnnotation(PersistedRank.class);
            List<SortClause> parsed = parseSortClauses(ann.sort_columns(), idCol, nonId);
            if (parsed.isEmpty()) parsed = defaultSort;
            resolvedRanks.add(new RankDef(rank.field(), rank.handle(), rank.name(), parsed, rank.loadOnDeserialize()));
        }

        PersistedJson persistedJson = entityType.getAnnotation(PersistedJson.class);
        PersistedJsonMode configured = persistedJson == null ? PersistedJsonMode.AUTO : persistedJson.mode();
        PersistedJsonMode jsonMode = configured == PersistedJsonMode.AUTO
                ? (resolvedRanks.isEmpty() ? PersistedJsonMode.LOAD_ON_DEMAND : PersistedJsonMode.LOAD_ALL)
                : configured;

        return new EntityModel<>(
                entityType,
                idType,
                namespace,
                idCol,
                nonId,
                indexes,
                relations,
                blobs,
                constructor(entityType),
                jsonMode,
                List.copyOf(resolvedRanks)
        );
    }

    private static List<Column> parseEmbedded(Field rootField, PersistedEmbedded embedded) {
        List<Column> out = new ArrayList<>();
        String prefix = embedded.prefix().isBlank() ? snake(rootField.getName()) + "_" : embedded.prefix();
        VarHandle rootHandle = varHandle(rootField);
        Constructor<?> rootConstructor = constructor(rootField.getType());

        for (Field nested : rootField.getType().getDeclaredFields()) {
            nested.setAccessible(true);
            int mod = nested.getModifiers();
            if (java.lang.reflect.Modifier.isStatic(mod) || java.lang.reflect.Modifier.isTransient(mod) || nested.isSynthetic()) {
                continue;
            }

            PersistedColumn nestedCol = nested.getAnnotation(PersistedColumn.class);
            String baseName = nestedCol == null || nestedCol.value().isBlank() ? snake(nested.getName()) : nestedCol.value();
            boolean nullable = nestedCol == null || nestedCol.nullable();
            String defaultValue = nestedCol == null ? "" : nestedCol.defaultValue();
            int length = nestedCol == null ? 255 : nestedCol.length();
            out.add(new Column(rootField, nested, prefix + baseName, nested.getType(), nullable, defaultValue, length, false,
                    rootHandle, varHandle(nested), rootConstructor));
        }

        return out;
    }

    private static RelationDef parseRelation(Field field, PersistedRelation relation, Field idField) {
        if (!(field.getGenericType() instanceof ParameterizedType pt)) {
            throw new IllegalArgumentException("@PersistedRelation field must be parameterized: " + field.getName());
        }

        Type raw = pt.getRawType();
        if (!(raw instanceof Class<?> rawClass) || !java.util.Collection.class.isAssignableFrom(rawClass)) {
            throw new IllegalArgumentException("@PersistedRelation currently supports Collection/List/Set only: " + field.getName());
        }

        Type elementTypeArg = pt.getActualTypeArguments()[0];
        if (!(elementTypeArg instanceof Class<?> elementType)) {
            throw new IllegalArgumentException("Unsupported @PersistedRelation element type on " + field.getName());
        }

        String joinColumn = relation.joinColumn().isBlank()
                ? snake(idField.getName())
                : relation.joinColumn();
        String valueColumn = relation.valueColumn();
        String orderColumn = relation.orderColumn();

        boolean simple = EntityTypeMapper.isSupportedType(elementType);
        if (simple && valueColumn.isBlank()) {
            throw new IllegalArgumentException("@PersistedRelation valueColumn is required for simple element type on field " + field.getName());
        }

        List<RelationColumn> objectColumns = new ArrayList<>();
        Constructor<?> elementConstructor = null;
        if (!simple) {
            if (!valueColumn.isBlank()) {
                throw new IllegalArgumentException("@PersistedRelation valueColumn must be empty for object element type on field " + field.getName());
            }
            String prefix = relation.prefix().isBlank() ? snake(field.getName()) + "_" : relation.prefix();
            elementConstructor = constructor(elementType);
            for (Field nested : elementType.getDeclaredFields()) {
                nested.setAccessible(true);
                int mod = nested.getModifiers();
                if (java.lang.reflect.Modifier.isStatic(mod) || java.lang.reflect.Modifier.isTransient(mod) || nested.isSynthetic()) {
                    continue;
                }
                PersistedColumn nestedCol = nested.getAnnotation(PersistedColumn.class);
                String baseName = nestedCol == null || nestedCol.value().isBlank() ? snake(nested.getName()) : nestedCol.value();
                int length = nestedCol == null ? 255 : nestedCol.length();
                objectColumns.add(new RelationColumn(nested, prefix + baseName, nested.getType(), length, varHandle(nested)));
            }

            if (objectColumns.isEmpty()) {
                throw new IllegalArgumentException("@PersistedRelation object field has no serializable nested fields: " + field.getName());
            }
        }

        return new RelationDef(field, varHandle(field), elementConstructor, relation.table(), joinColumn, valueColumn, orderColumn,
                elementType, simple, objectColumns);
    }

    private static List<IndexDef> parseIndexes(Class<?> type) {
        List<IndexDef> out = new ArrayList<>();

        PersistedIndex one = type.getAnnotation(PersistedIndex.class);
        if (one != null) {
            out.add(toIndex(one, type.getSimpleName()));
        }

        PersistedIndexes many = type.getAnnotation(PersistedIndexes.class);
        if (many != null) {
            for (PersistedIndex index : many.value()) {
                out.add(toIndex(index, type.getSimpleName()));
            }
        }

        return out;
    }

    private static IndexDef toIndex(PersistedIndex ann, String entityName) {
        if (ann.columns().length == 0) {
            throw new IllegalArgumentException("@PersistedIndex on " + entityName + " has no columns");
        }
        String desired = ann.name().isBlank()
                ? "idx_" + snake(entityName) + "_" + String.join("_", ann.columns())
                : ann.name();
        return new IndexDef(shortenIndexName(desired), List.of(ann.columns()), ann.unique());
    }

    private static String shortenIndexName(String value) {
        String normalized = value.toLowerCase(Locale.ROOT);
        if (normalized.length() <= MAX_INDEX_NAME_LENGTH) {
            return normalized;
        }

        String hash = String.format(Locale.ROOT, "%08x", normalized.hashCode());
        int prefixLength = MAX_INDEX_NAME_LENGTH - 9;
        return normalized.substring(0, prefixLength) + "_" + hash;
    }

    private static String snake(String input) {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (Character.isUpperCase(c) && i > 0) {
                out.append('_');
            }
            out.append(Character.toLowerCase(c));
        }
        return out.toString();
    }

    private static VarHandle varHandle(Field field) {
        try {
            return MethodHandles.privateLookupIn(field.getDeclaringClass(), MethodHandles.lookup()).unreflectVarHandle(field);
        } catch (IllegalAccessException e) {
            throw new IllegalArgumentException("Unable to create VarHandle for field " + field.getDeclaringClass().getName() + "#" + field.getName(), e);
        }
    }

    @SuppressWarnings("unchecked")
    private static <V> Constructor<V> constructor(Class<?> type) {
        try {
            Constructor<V> constructor = (Constructor<V>) type.getDeclaredConstructor();
            constructor.setAccessible(true);
            return constructor;
        } catch (NoSuchMethodException e) {
            throw new IllegalArgumentException("Type requires a no-arg constructor: " + type.getName(), e);
        }
    }

    private static BlobDef parseBlob(Field field, PersistedBlob blob) {
        String name = blob.value().isBlank() ? snake(field.getName()) : blob.value();

        Class<? extends PersistedBlobSerializer<?>> serializerClass = blob.serializer();
        PersistedBlobSerializer<Object> serializer = PersistedBlobSerializers.resolve(field.getType(), serializerClass);

        boolean hasExplicitSerializer = serializerClass != null && serializerClass != NoPersistedBlobSerializer.class;
        boolean binaryStorage = fr.ibrakash.helper.binary.BinaryStorage.class.isAssignableFrom(field.getType());
        boolean rawBytes = field.getType() == byte[].class;

        if (!binaryStorage && !rawBytes && serializer == null) {
            throw new IllegalArgumentException("@PersistedBlob field requires a serializer or BinaryStorage type: " + field.getName());
        }

        Constructor<?> storageCtor = null;
        if (binaryStorage) {
            storageCtor = constructor(field.getType());
            if (!hasExplicitSerializer && serializer == null) {
                serializer = null; // BinaryStorage handles serialization itself.
            }
        }

        return new BlobDef(
                field,
                varHandle(field),
                name,
                field.getType(),
                blob.nullable(),
                blob.kind(),
                blob.blobTier(),
                blob.length(),
                serializerClass,
                serializer,
                storageCtor
        );
    }

    private static List<SortClause> parseSortClauses(String[] values, Column idColumn, List<Column> columns) {
        if (values == null || values.length == 0) {
            return List.of();
        }
        List<SortClause> out = new ArrayList<>(values.length);
        for (String raw : values) {
            if (raw == null || raw.isBlank()) continue;
            String spec = raw.trim();
            String[] parts = spec.split("\\s+");
            String field = parts[0];
            SortDirection direction = SortDirection.ASC;
            if (parts.length > 1 && parts[1].equalsIgnoreCase("DESC")) {
                direction = SortDirection.DESC;
            }
            String resolved = resolveSortColumnName(field, idColumn, columns);
            out.add(new SortClause(resolved, direction));
        }
        return out;
    }

    private static String resolveSortColumnName(String fieldOrColumn, Column idColumn, List<Column> columns) {
        if (matchesColumn(idColumn, fieldOrColumn)) {
            return idColumn.name();
        }
        for (Column column : columns) {
            if (matchesColumn(column, fieldOrColumn)) {
                return column.name();
            }
        }
        throw new IllegalArgumentException("Unknown rank/sort field '" + fieldOrColumn + "'");
    }

    private static boolean matchesColumn(Column column, String fieldOrColumn) {
        String normalized = fieldOrColumn.toLowerCase(Locale.ROOT);
        if (column.name().equalsIgnoreCase(normalized)) {
            return true;
        }
        return column.leafField().getName().equalsIgnoreCase(normalized);
    }

    public T newEntity() {
        try {
            return this.entityConstructor.newInstance();
        } catch (Exception e) {
            throw new RuntimeException("Unable to instantiate entity " + this.entityType.getName(), e);
        }
    }

    public Object newRelationElement(RelationDef relation) {
        try {
            return relation.elementConstructor().newInstance();
        } catch (Exception e) {
            throw new RuntimeException("Unable to instantiate relation element for field " + relation.field().getName(), e);
        }
    }

    public ID idOf(T entity) {
        Object value = readColumnValue(entity, this.idColumn);
        return this.idType.cast(value);
    }

    public Column resolveColumn(String fieldOrColumn) {
        if (fieldOrColumn == null || fieldOrColumn.isBlank()) {
            throw new IllegalArgumentException("Sort field cannot be blank");
        }

        if (matchesColumn(this.idColumn, fieldOrColumn)) {
            return this.idColumn;
        }

        Optional<Column> resolved = this.columns.stream()
                .filter(column -> matchesColumn(column, fieldOrColumn))
                .findFirst();
        return resolved.orElseThrow(() -> new IllegalArgumentException(
                "Unknown sortable field '" + fieldOrColumn + "' for " + this.entityType.getSimpleName()
        ));
    }

    public Object readColumnRawValue(T entity, String fieldOrColumn) {
        Column column = resolveColumn(fieldOrColumn);
        return readColumnValue(entity, column);
    }

    public Object readColumnValue(T entity, Column column) {
        if (column.rootHandle() == null) {
            return column.leafHandle().get(entity);
        }
        Object embedded = column.rootHandle().get(entity);
        if (embedded == null) return null;
        return column.leafHandle().get(embedded);
    }

    public void writeColumnValue(T entity, Column column, Object value) {
        if (column.rootHandle() == null) {
            column.leafHandle().set(entity, value);
            return;
        }

        Object embedded = column.rootHandle().get(entity);
        if (embedded == null) {
            try {
                embedded = column.rootConstructor().newInstance();
            } catch (Exception e) {
                throw new RuntimeException("Unable to instantiate embedded object for field " + column.rootField().getName(), e);
            }
            column.rootHandle().set(entity, embedded);
        }
        column.leafHandle().set(embedded, value);
    }

    public Object readRelationField(T entity, RelationDef relation) {
        return relation.collectionHandle().get(entity);
    }

    public void writeRelationField(T entity, RelationDef relation, Object value) {
        relation.collectionHandle().set(entity, value);
    }

    public Object readRelationColumnValue(Object element, RelationColumn column) {
        return column.handle().get(element);
    }

    public void writeRelationColumnValue(Object element, RelationColumn column, Object value) {
        column.handle().set(element, value);
    }

    public void writeRankValue(T entity, RankDef rank, int value) {
        rank.handle().set(entity, value);
    }

    public List<BlobDef> blobs() {
        return blobs;
    }

    public Class<T> entityType() {
        return entityType;
    }

    public Class<ID> idType() {
        return idType;
    }

    public String namespace() {
        return namespace;
    }

    public Column idColumn() {
        return idColumn;
    }

    public List<Column> columns() {
        return columns;
    }

    public List<IndexDef> indexes() {
        return indexes;
    }


    public List<RelationDef> relations() {
        return relations;
    }

    public PersistedJsonMode jsonMode() {
        return jsonMode;
    }

    public List<RankDef> ranks() {
        return ranks;
    }

    public Optional<RankDef> rank(String name) {
        if (name == null || name.isBlank()) return Optional.empty();
        return this.ranks.stream().filter(r -> r.name().equalsIgnoreCase(name)).findFirst();
    }

    public List<RankDef> ranksMarkedForDeserialize() {
        return this.ranks.stream().filter(RankDef::loadOnDeserialize).toList();
    }
}

package fr.ibrakash.helper.persistence.entity.internal;

import fr.ibrakash.helper.persistence.entity.NoPersistedBlobSerializer;
import fr.ibrakash.helper.persistence.entity.PersistedBlob;
import fr.ibrakash.helper.persistence.entity.PersistedBlobKind;
import fr.ibrakash.helper.persistence.entity.PersistedBlobSerializer;
import fr.ibrakash.helper.persistence.entity.PersistedBlobTier;
import fr.ibrakash.helper.persistence.entity.PersistedColumn;
import fr.ibrakash.helper.persistence.entity.PersistedEmbedded;
import fr.ibrakash.helper.persistence.entity.PersistedEntity;
import fr.ibrakash.helper.persistence.entity.PersistedId;
import fr.ibrakash.helper.persistence.entity.PersistedIndex;
import fr.ibrakash.helper.persistence.entity.PersistedIndexes;
import fr.ibrakash.helper.persistence.entity.PersistedRelation;
import fr.ibrakash.helper.persistence.entity.PersistedJson;
import fr.ibrakash.helper.persistence.entity.PersistedJsonMode;
import fr.ibrakash.helper.persistence.entity.PersistedRank;
import fr.ibrakash.helper.persistence.query.SortClause;
import fr.ibrakash.helper.persistence.query.SortDirection;

import java.lang.invoke.MethodHandles;
import java.lang.invoke.VarHandle;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Optional;

public final class EntityModel<T, ID> {

    private static final int MAX_INDEX_NAME_LENGTH = 63;

    public record Column(
            Field rootField,
            Field leafField,
            String name,
            Class<?> type,
            boolean nullable,
            String defaultValue,
            int length,
            boolean id,
            VarHandle rootHandle,
            VarHandle leafHandle,
            Constructor<?> rootConstructor
    ) {}

    public record IndexDef(String name, List<String> columns, boolean unique) {}

    public record RelationColumn(Field field, String name, Class<?> type, int length, VarHandle handle) {}

    public record RelationDef(
            Field field,
            VarHandle collectionHandle,
            Constructor<?> elementConstructor,
            String table,
            String joinColumn,
            String valueColumn,
            String orderColumn,
            Class<?> elementType,
            boolean simple,
            List<RelationColumn> objectColumns
    ) {}

    public record BlobDef(
            Field field,
            VarHandle handle,
            String name,
            Class<?> type,
            boolean nullable,
            PersistedBlobKind kind,
            PersistedBlobTier tier,
            int length,
            Class<? extends PersistedBlobSerializer<?>> serializerClass,
            PersistedBlobSerializer<Object> serializer,
            Constructor<?> binaryStorageConstructor
    ) {}

    public record RankDef(
            Field field,
            VarHandle handle,
            String name,
            List<SortClause> sorts,
            boolean loadOnDeserialize
    ) {}

    private final Class<T> entityType;
    private final Class<ID> idType;
    private final String namespace;
    private final Column idColumn;
    private final List<Column> columns;
    private final List<IndexDef> indexes;
    private final List<RelationDef> relations;
    private final List<BlobDef> blobs;
    private final Constructor<T> entityConstructor;
    private final PersistedJsonMode jsonMode;
    private final List<RankDef> ranks;

    private EntityModel(Class<T> entityType,
                        Class<ID> idType,
                        String namespace,
                        Column idColumn,
                        List<Column> columns,
                        List<IndexDef> indexes,
                        List<RelationDef> relations,
                        List<BlobDef> blobs,
                        Constructor<T> entityConstructor,
                        PersistedJsonMode jsonMode,
                        List<RankDef> ranks) {
        this.entityType = entityType;
        this.idType = idType;
        this.namespace = namespace;
        this.idColumn = idColumn;
        this.columns = columns;
        this.indexes = indexes;
        this.relations = relations;
        this.blobs = blobs;
        this.entityConstructor = entityConstructor;
        this.jsonMode = jsonMode;
        this.ranks = ranks;
    }

    public static <T, ID> EntityModel<T, ID> from(Class<T> entityType, Class<ID> idType) {
        Field idField = null;
        List<Column> cols = new ArrayList<>();
        List<RelationDef> relations = new ArrayList<>();
        List<BlobDef> blobs = new ArrayList<>();
        List<RankDef> ranks = new ArrayList<>();

        for (Field field : entityType.getDeclaredFields()) {
            field.setAccessible(true);

            PersistedId id = field.getAnnotation(PersistedId.class);
            PersistedRelation relation = field.getAnnotation(PersistedRelation.class);
            PersistedEmbedded embedded = field.getAnnotation(PersistedEmbedded.class);
            PersistedColumn col = field.getAnnotation(PersistedColumn.class);
            PersistedBlob blob = field.getAnnotation(PersistedBlob.class);
            PersistedRank rank = field.getAnnotation(PersistedRank.class);

            if (id != null) {
                if (idField != null) {
                    throw new IllegalArgumentException("Multiple @PersistedId fields in " + entityType.getName());
                }
                String name = id.value().isBlank() ? snake(field.getName()) : id.value();
                idField = field;
                cols.add(new Column(null, field, name, field.getType(), false, "", 36, true,
                        null, varHandle(field), null));
                continue;
            }

            if (relation != null) {
                continue;
            }

            if (rank != null) {
                int mod = field.getModifiers();
                if (!java.lang.reflect.Modifier.isTransient(mod)) {
                    throw new IllegalArgumentException("@PersistedRank field must be transient: " + entityType.getName() + "#" + field.getName());
                }
                ranks.add(new RankDef(field, varHandle(field), field.getName(), List.of(), rank.load_on_deserialize()));
                continue;
            }

            if (embedded != null) {
                cols.addAll(parseEmbedded(field, embedded));
                continue;
            }

            if (blob != null) {
                blobs.add(parseBlob(field, blob));
                continue;
            }

            if (col == null) {
                int mod = field.getModifiers();
                if (java.lang.reflect.Modifier.isStatic(mod) || java.lang.reflect.Modifier.isTransient(mod) || field.isSynthetic()) {
                    continue;
                }
                cols.add(new Column(null, field, snake(field.getName()), field.getType(), true, "", 255, false,
                        null, varHandle(field), null));
            } else {
                String name = col.value().isBlank() ? snake(field.getName()) : col.value();
                cols.add(new Column(null, field, name, field.getType(), col.nullable(), col.defaultValue(), col.length(), false,
                        null, varHandle(field), null));
            }
        }

        if (idField == null) {
            throw new IllegalArgumentException("Missing @PersistedId field in " + entityType.getName());
        }

        for (Field field : entityType.getDeclaredFields()) {
            PersistedRelation relation = field.getAnnotation(PersistedRelation.class);
            if (relation == null) continue;
            field.setAccessible(true);
            relations.add(parseRelation(field, relation, idField));
        }

        Column idCol = cols.stream().filter(Column::id).findFirst().orElseThrow();
        List<Column> nonId = cols.stream().filter(c -> !c.id()).toList();

        PersistedEntity entityAnn = entityType.getAnnotation(PersistedEntity.class);
        String namespace = entityAnn != null && !entityAnn.value().isBlank()
                ? entityAnn.value()
                : snake(entityType.getSimpleName());

        List<IndexDef> indexes = parseIndexes(entityType);

        List<SortClause> defaultSort = List.of(new SortClause(idCol.name(), SortDirection.ASC));
        List<RankDef> resolvedRanks = new ArrayList<>(ranks.size());
        for (RankDef rank : ranks) {
            PersistedRank ann = rank.field().getAnnotation(PersistedRank.class);
            List<SortClause> parsed = parseSortClauses(ann.sort_columns(), idCol, nonId);
            if (parsed.isEmpty()) parsed = defaultSort;
            resolvedRanks.add(new RankDef(rank.field(), rank.handle(), rank.name(), parsed, rank.loadOnDeserialize()));
        }

        PersistedJson persistedJson = entityType.getAnnotation(PersistedJson.class);
        PersistedJsonMode configured = persistedJson == null ? PersistedJsonMode.AUTO : persistedJson.mode();
        PersistedJsonMode jsonMode = configured == PersistedJsonMode.AUTO
                ? (resolvedRanks.isEmpty() ? PersistedJsonMode.LOAD_ON_DEMAND : PersistedJsonMode.LOAD_ALL)
                : configured;

        return new EntityModel<>(
                entityType,
                idType,
                namespace,
                idCol,
                nonId,
                indexes,
                relations,
                blobs,
                constructor(entityType),
                jsonMode,
                List.copyOf(resolvedRanks)
        );
    }

    private static List<Column> parseEmbedded(Field rootField, PersistedEmbedded embedded) {
        List<Column> out = new ArrayList<>();
        String prefix = embedded.prefix().isBlank() ? snake(rootField.getName()) + "_" : embedded.prefix();
        VarHandle rootHandle = varHandle(rootField);
        Constructor<?> rootConstructor = constructor(rootField.getType());

        for (Field nested : rootField.getType().getDeclaredFields()) {
            nested.setAccessible(true);
            int mod = nested.getModifiers();
            if (java.lang.reflect.Modifier.isStatic(mod) || java.lang.reflect.Modifier.isTransient(mod) || nested.isSynthetic()) {
                continue;
            }

            PersistedColumn nestedCol = nested.getAnnotation(PersistedColumn.class);
            String baseName = nestedCol == null || nestedCol.value().isBlank() ? snake(nested.getName()) : nestedCol.value();
            boolean nullable = nestedCol == null || nestedCol.nullable();
            String defaultValue = nestedCol == null ? "" : nestedCol.defaultValue();
            int length = nestedCol == null ? 255 : nestedCol.length();
            out.add(new Column(rootField, nested, prefix + baseName, nested.getType(), nullable, defaultValue, length, false,
                    rootHandle, varHandle(nested), rootConstructor));
        }

        return out;
    }

    private static RelationDef parseRelation(Field field, PersistedRelation relation, Field idField) {
        if (!(field.getGenericType() instanceof ParameterizedType pt)) {
            throw new IllegalArgumentException("@PersistedRelation field must be parameterized: " + field.getName());
        }

        Type raw = pt.getRawType();
        if (!(raw instanceof Class<?> rawClass) || !java.util.Collection.class.isAssignableFrom(rawClass)) {
            throw new IllegalArgumentException("@PersistedRelation currently supports Collection/List/Set only: " + field.getName());
        }

        Type elementTypeArg = pt.getActualTypeArguments()[0];
        if (!(elementTypeArg instanceof Class<?> elementType)) {
            throw new IllegalArgumentException("Unsupported @PersistedRelation element type on " + field.getName());
        }

        String joinColumn = relation.joinColumn().isBlank()
                ? snake(idField.getName())
                : relation.joinColumn();
        String valueColumn = relation.valueColumn();
        String orderColumn = relation.orderColumn();

        boolean simple = EntityTypeMapper.isSupportedType(elementType);
        if (simple && valueColumn.isBlank()) {
            throw new IllegalArgumentException("@PersistedRelation valueColumn is required for simple element type on field " + field.getName());
        }

        List<RelationColumn> objectColumns = new ArrayList<>();
        Constructor<?> elementConstructor = null;
        if (!simple) {
            if (!valueColumn.isBlank()) {
                throw new IllegalArgumentException("@PersistedRelation valueColumn must be empty for object element type on field " + field.getName());
            }
            String prefix = relation.prefix().isBlank() ? snake(field.getName()) + "_" : relation.prefix();
            elementConstructor = constructor(elementType);
            for (Field nested : elementType.getDeclaredFields()) {
                nested.setAccessible(true);
                int mod = nested.getModifiers();
                if (java.lang.reflect.Modifier.isStatic(mod) || java.lang.reflect.Modifier.isTransient(mod) || nested.isSynthetic()) {
                    continue;
                }
                PersistedColumn nestedCol = nested.getAnnotation(PersistedColumn.class);
                String baseName = nestedCol == null || nestedCol.value().isBlank() ? snake(nested.getName()) : nestedCol.value();
                int length = nestedCol == null ? 255 : nestedCol.length();
                objectColumns.add(new RelationColumn(nested, prefix + baseName, nested.getType(), length, varHandle(nested)));
            }

            if (objectColumns.isEmpty()) {
                throw new IllegalArgumentException("@PersistedRelation object field has no serializable nested fields: " + field.getName());
            }
        }

        return new RelationDef(field, varHandle(field), elementConstructor, relation.table(), joinColumn, valueColumn, orderColumn,
                elementType, simple, objectColumns);
    }

    private static List<IndexDef> parseIndexes(Class<?> type) {
        List<IndexDef> out = new ArrayList<>();

        PersistedIndex one = type.getAnnotation(PersistedIndex.class);
        if (one != null) {
            out.add(toIndex(one, type.getSimpleName()));
        }

        PersistedIndexes many = type.getAnnotation(PersistedIndexes.class);
        if (many != null) {
            for (PersistedIndex index : many.value()) {
                out.add(toIndex(index, type.getSimpleName()));
            }
        }

        return out;
    }

    private static IndexDef toIndex(PersistedIndex ann, String entityName) {
        if (ann.columns().length == 0) {
            throw new IllegalArgumentException("@PersistedIndex on " + entityName + " has no columns");
        }
        String desired = ann.name().isBlank()
                ? "idx_" + snake(entityName) + "_" + String.join("_", ann.columns())
                : ann.name();
        return new IndexDef(shortenIndexName(desired), List.of(ann.columns()), ann.unique());
    }

    private static String shortenIndexName(String value) {
        String normalized = value.toLowerCase(Locale.ROOT);
        if (normalized.length() <= MAX_INDEX_NAME_LENGTH) {
            return normalized;
        }

        String hash = String.format(Locale.ROOT, "%08x", normalized.hashCode());
        int prefixLength = MAX_INDEX_NAME_LENGTH - 9;
        return normalized.substring(0, prefixLength) + "_" + hash;
    }

    private static String snake(String input) {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (Character.isUpperCase(c) && i > 0) {
                out.append('_');
            }
            out.append(Character.toLowerCase(c));
        }
        return out.toString();
    }

    private static VarHandle varHandle(Field field) {
        try {
            return MethodHandles.privateLookupIn(field.getDeclaringClass(), MethodHandles.lookup()).unreflectVarHandle(field);
        } catch (IllegalAccessException e) {
            throw new IllegalArgumentException("Unable to create VarHandle for field " + field.getDeclaringClass().getName() + "#" + field.getName(), e);
        }
    }

    @SuppressWarnings("unchecked")
    private static <V> Constructor<V> constructor(Class<?> type) {
        try {
            Constructor<V> constructor = (Constructor<V>) type.getDeclaredConstructor();
            constructor.setAccessible(true);
            return constructor;
        } catch (NoSuchMethodException e) {
            throw new IllegalArgumentException("Type requires a no-arg constructor: " + type.getName(), e);
        }
    }

    private static BlobDef parseBlob(Field field, PersistedBlob blob) {
        String name = blob.value().isBlank() ? snake(field.getName()) : blob.value();

        Class<? extends PersistedBlobSerializer<?>> serializerClass = blob.serializer();
        PersistedBlobSerializer<Object> serializer = PersistedBlobSerializers.resolve(field.getType(), field.getGenericType(), serializerClass);

        boolean hasExplicitSerializer = serializerClass != null && serializerClass != NoPersistedBlobSerializer.class;
        boolean binaryStorage = fr.ibrakash.helper.binary.BinaryStorage.class.isAssignableFrom(field.getType());
        boolean rawBytes = field.getType() == byte[].class;

        if (!binaryStorage && !rawBytes && serializer == null) {
            throw new IllegalArgumentException("@PersistedBlob field requires a serializer or BinaryStorage type: " + field.getName());
        }

        Constructor<?> storageCtor = null;
        if (binaryStorage) {
            storageCtor = constructor(field.getType());
            if (!hasExplicitSerializer && serializer == null) {
                serializer = null; // BinaryStorage handles serialization itself.
            }
        }

        return new BlobDef(
                field,
                varHandle(field),
                name,
                field.getType(),
                blob.nullable(),
                blob.kind(),
                blob.blobTier(),
                blob.length(),
                serializerClass,
                serializer,
                storageCtor
        );
    }

    private static List<SortClause> parseSortClauses(String[] values, Column idColumn, List<Column> columns) {
        if (values == null || values.length == 0) {
            return List.of();
        }
        List<SortClause> out = new ArrayList<>(values.length);
        for (String raw : values) {
            if (raw == null || raw.isBlank()) continue;
            String spec = raw.trim();
            String[] parts = spec.split("\\s+");
            String field = parts[0];
            SortDirection direction = SortDirection.ASC;
            if (parts.length > 1 && parts[1].equalsIgnoreCase("DESC")) {
                direction = SortDirection.DESC;
            }
            String resolved = resolveSortColumnName(field, idColumn, columns);
            out.add(new SortClause(resolved, direction));
        }
        return out;
    }

    private static String resolveSortColumnName(String fieldOrColumn, Column idColumn, List<Column> columns) {
        if (matchesColumn(idColumn, fieldOrColumn)) {
            return idColumn.name();
        }
        for (Column column : columns) {
            if (matchesColumn(column, fieldOrColumn)) {
                return column.name();
            }
        }
        throw new IllegalArgumentException("Unknown rank/sort field '" + fieldOrColumn + "'");
    }

    private static boolean matchesColumn(Column column, String fieldOrColumn) {
        String normalized = fieldOrColumn.toLowerCase(Locale.ROOT);
        if (column.name().equalsIgnoreCase(normalized)) {
            return true;
        }
        return column.leafField().getName().equalsIgnoreCase(normalized);
    }

    public T newEntity() {
        try {
            return this.entityConstructor.newInstance();
        } catch (Exception e) {
            throw new RuntimeException("Unable to instantiate entity " + this.entityType.getName(), e);
        }
    }

    public Object newRelationElement(RelationDef relation) {
        try {
            return relation.elementConstructor().newInstance();
        } catch (Exception e) {
            throw new RuntimeException("Unable to instantiate relation element for field " + relation.field().getName(), e);
        }
    }

    public ID idOf(T entity) {
        Object value = readColumnValue(entity, this.idColumn);
        return this.idType.cast(value);
    }

    public Column resolveColumn(String fieldOrColumn) {
        if (fieldOrColumn == null || fieldOrColumn.isBlank()) {
            throw new IllegalArgumentException("Sort field cannot be blank");
        }

        if (matchesColumn(this.idColumn, fieldOrColumn)) {
            return this.idColumn;
        }

        Optional<Column> resolved = this.columns.stream()
                .filter(column -> matchesColumn(column, fieldOrColumn))
                .findFirst();
        return resolved.orElseThrow(() -> new IllegalArgumentException(
                "Unknown sortable field '" + fieldOrColumn + "' for " + this.entityType.getSimpleName()
        ));
    }

    public Object readColumnRawValue(T entity, String fieldOrColumn) {
        Column column = resolveColumn(fieldOrColumn);
        return readColumnValue(entity, column);
    }

    public Object readColumnValue(T entity, Column column) {
        if (column.rootHandle() == null) {
            return column.leafHandle().get(entity);
        }
        Object embedded = column.rootHandle().get(entity);
        if (embedded == null) return null;
        return column.leafHandle().get(embedded);
    }

    public void writeColumnValue(T entity, Column column, Object value) {
        if (column.rootHandle() == null) {
            column.leafHandle().set(entity, value);
            return;
        }

        Object embedded = column.rootHandle().get(entity);
        if (embedded == null) {
            try {
                embedded = column.rootConstructor().newInstance();
            } catch (Exception e) {
                throw new RuntimeException("Unable to instantiate embedded object for field " + column.rootField().getName(), e);
            }
            column.rootHandle().set(entity, embedded);
        }
        column.leafHandle().set(embedded, value);
    }

    public Object readRelationField(T entity, RelationDef relation) {
        return relation.collectionHandle().get(entity);
    }

    public void writeRelationField(T entity, RelationDef relation, Object value) {
        relation.collectionHandle().set(entity, value);
    }

    public Object readRelationColumnValue(Object element, RelationColumn column) {
        return column.handle().get(element);
    }

    public void writeRelationColumnValue(Object element, RelationColumn column, Object value) {
        column.handle().set(element, value);
    }

    public void writeRankValue(T entity, RankDef rank, int value) {
        rank.handle().set(entity, value);
    }

    public List<BlobDef> blobs() {
        return blobs;
    }

    public Class<T> entityType() {
        return entityType;
    }

    public Class<ID> idType() {
        return idType;
    }

    public String namespace() {
        return namespace;
    }

    public Column idColumn() {
        return idColumn;
    }

    public List<Column> columns() {
        return columns;
    }

    public List<IndexDef> indexes() {
        return indexes;
    }


    public List<RelationDef> relations() {
        return relations;
    }

    public PersistedJsonMode jsonMode() {
        return jsonMode;
    }

    public List<RankDef> ranks() {
        return ranks;
    }

    public Optional<RankDef> rank(String name) {
        if (name == null || name.isBlank()) return Optional.empty();
        return this.ranks.stream().filter(r -> r.name().equalsIgnoreCase(name)).findFirst();
    }

    public List<RankDef> ranksMarkedForDeserialize() {
        return this.ranks.stream().filter(RankDef::loadOnDeserialize).toList();
    }
}

package fr.ibrakash.helper.persistence.entity.internal;

import fr.ibrakash.helper.persistence.entity.NoPersistedBlobSerializer;
import fr.ibrakash.helper.persistence.entity.PersistedBlobSerializer;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

final class PersistedBlobSerializers {

    private static final Map<Class<?>, PersistedBlobSerializer<?>> DEFAULTS = new HashMap<>();

    static {
        DEFAULTS.put(byte[].class, new BytesSerializer());
        DEFAULTS.put(String.class, new StringSerializer());
        DEFAULTS.put(Integer.class, new IntegerSerializer());
        DEFAULTS.put(int.class, new IntegerSerializer());
        DEFAULTS.put(Long.class, new LongSerializer());
        DEFAULTS.put(long.class, new LongSerializer());
        DEFAULTS.put(Boolean.class, new BooleanSerializer());
        DEFAULTS.put(boolean.class, new BooleanSerializer());
        DEFAULTS.put(Double.class, new DoubleSerializer());
        DEFAULTS.put(double.class, new DoubleSerializer());
        DEFAULTS.put(Float.class, new FloatSerializer());
        DEFAULTS.put(float.class, new FloatSerializer());
        DEFAULTS.put(UUID.class, new UuidSerializer());
    }

    private PersistedBlobSerializers() {
    }

    @SuppressWarnings({"unchecked", "rawtypes"})
    static PersistedBlobSerializer<Object> resolve(Class<?> fieldType,
                                                   Class<? extends PersistedBlobSerializer<?>> serializerClass) {
        if (serializerClass != null && serializerClass != NoPersistedBlobSerializer.class) {
            try {
                return (PersistedBlobSerializer<Object>) serializerClass.getDeclaredConstructor().newInstance();
            } catch (Exception e) {
                throw new IllegalArgumentException("Unable to instantiate blob serializer " + serializerClass.getName(), e);
            }
        }

        PersistedBlobSerializer<?> serializer = DEFAULTS.get(fieldType);
        if (serializer != null) {
            return (PersistedBlobSerializer<Object>) serializer;
        }

        if (fieldType.isEnum()) {
            return new EnumSerializer((Class<? extends Enum>) fieldType);
        }

        return null;
    }

    private static final class BytesSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            return value == null ? new byte[0] : (byte[]) value;
        }

        @Override
        public Object deserialize(byte[] bytes) {
            return bytes == null ? new byte[0] : bytes;
        }
    }

    private static final class StringSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            return value == null ? new byte[0] : ((String) value).getBytes(StandardCharsets.UTF_8);
        }

        @Override
        public Object deserialize(byte[] bytes) {
            return bytes == null ? "" : new String(bytes, StandardCharsets.UTF_8);
        }
    }

    private static final class IntegerSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            try (ByteArrayOutputStream out = new ByteArrayOutputStream();
                 DataOutputStream data = new DataOutputStream(out)) {
                data.writeInt(value == null ? 0 : (Integer) value);
                return out.toByteArray();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public Object deserialize(byte[] bytes) {
            if (bytes == null || bytes.length == 0) return 0;
            try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(bytes))) {
                return in.readInt();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    private static final class LongSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            try (ByteArrayOutputStream out = new ByteArrayOutputStream();
                 DataOutputStream data = new DataOutputStream(out)) {
                data.writeLong(value == null ? 0L : (Long) value);
                return out.toByteArray();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public Object deserialize(byte[] bytes) {
            if (bytes == null || bytes.length == 0) return 0L;
            try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(bytes))) {
                return in.readLong();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    private static final class BooleanSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            return new byte[] {(byte) (((value != null) && ((Boolean) value)) ? 1 : 0)};
        }

        @Override
        public Object deserialize(byte[] bytes) {
            return bytes != null && bytes.length > 0 && bytes[0] != 0;
        }
    }

    private static final class DoubleSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            try (ByteArrayOutputStream out = new ByteArrayOutputStream();
                 DataOutputStream data = new DataOutputStream(out)) {
                data.writeDouble(value == null ? 0D : (Double) value);
                return out.toByteArray();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public Object deserialize(byte[] bytes) {
            if (bytes == null || bytes.length == 0) return 0D;
            try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(bytes))) {
                return in.readDouble();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    private static final class FloatSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            try (ByteArrayOutputStream out = new ByteArrayOutputStream();
                 DataOutputStream data = new DataOutputStream(out)) {
                data.writeFloat(value == null ? 0F : (Float) value);
                return out.toByteArray();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public Object deserialize(byte[] bytes) {
            if (bytes == null || bytes.length == 0) return 0F;
            try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(bytes))) {
                return in.readFloat();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    private static final class UuidSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            return value == null ? new byte[0] : value.toString().getBytes(StandardCharsets.UTF_8);
        }

        @Override
        public Object deserialize(byte[] bytes) {
            if (bytes == null || bytes.length == 0) return null;
            return UUID.fromString(new String(bytes, StandardCharsets.UTF_8));
        }
    }

    private static final class EnumSerializer implements PersistedBlobSerializer<Object> {

        private final Class<? extends Enum> enumType;

        private EnumSerializer(Class<? extends Enum> enumType) {
            this.enumType = enumType;
        }

        @Override
        public byte[] serialize(Object value) {
            return value == null ? new byte[0] : ((Enum<?>) value).name().getBytes(StandardCharsets.UTF_8);
        }

        @Override
        public Object deserialize(byte[] bytes) {
            if (bytes == null || bytes.length == 0) return null;
            return Enum.valueOf(this.enumType, new String(bytes, StandardCharsets.UTF_8));
        }
    }
}

package fr.ibrakash.helper.persistence.entity.internal;

import fr.ibrakash.helper.persistence.entity.NoPersistedBlobSerializer;
import fr.ibrakash.helper.persistence.entity.PersistedBlobSerializer;
import fr.ibrakash.helper.persistence.entity.PersistedBlobSerializerRegistry;

import java.io.*;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

final class PersistedBlobSerializers {

    private static final Map<Class<?>, PersistedBlobSerializer<?>> DEFAULTS = new HashMap<>();

    static {
        DEFAULTS.put(byte[].class, new BytesSerializer());
        DEFAULTS.put(String.class, new StringSerializer());
        DEFAULTS.put(Integer.class, new IntegerSerializer());
        DEFAULTS.put(int.class, new IntegerSerializer());
        DEFAULTS.put(Long.class, new LongSerializer());
        DEFAULTS.put(long.class, new LongSerializer());
        DEFAULTS.put(Boolean.class, new BooleanSerializer());
        DEFAULTS.put(boolean.class, new BooleanSerializer());
        DEFAULTS.put(Double.class, new DoubleSerializer());
        DEFAULTS.put(double.class, new DoubleSerializer());
        DEFAULTS.put(Float.class, new FloatSerializer());
        DEFAULTS.put(float.class, new FloatSerializer());
        DEFAULTS.put(UUID.class, new UuidSerializer());
    }

    private PersistedBlobSerializers() {
    }

    @SuppressWarnings({"unchecked", "rawtypes"})
    static PersistedBlobSerializer<Object> resolve(Class<?> fieldType,
                                                   Type genericType,
                                                   Class<? extends PersistedBlobSerializer<?>> serializerClass) {
        if (serializerClass != null && serializerClass != NoPersistedBlobSerializer.class) {
            try {
                return (PersistedBlobSerializer<Object>) serializerClass.getDeclaredConstructor().newInstance();
            } catch (Exception e) {
                throw new IllegalArgumentException("Unable to instantiate blob serializer " + serializerClass.getName(), e);
            }
        }

        PersistedBlobSerializer<Object> registered = PersistedBlobSerializerRegistry.resolve(genericType);
        if (registered != null) {
            return registered;
        }

        registered = PersistedBlobSerializerRegistry.resolve(fieldType);
        if (registered != null) {
            return registered;
        }

        PersistedBlobSerializer<?> serializer = DEFAULTS.get(fieldType);
        if (serializer != null) {
            return (PersistedBlobSerializer<Object>) serializer;
        }

        if (fieldType.isEnum()) {
            return new EnumSerializer((Class<? extends Enum>) fieldType);
        }

        return null;
    }

    private static final class BytesSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            return value == null ? new byte[0] : (byte[]) value;
        }

        @Override
        public Object deserialize(byte[] bytes) {
            return bytes == null ? new byte[0] : bytes;
        }
    }

    private static final class StringSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            return value == null ? new byte[0] : ((String) value).getBytes(StandardCharsets.UTF_8);
        }

        @Override
        public Object deserialize(byte[] bytes) {
            return bytes == null ? "" : new String(bytes, StandardCharsets.UTF_8);
        }
    }

    private static final class IntegerSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            try (ByteArrayOutputStream out = new ByteArrayOutputStream();
                 DataOutputStream data = new DataOutputStream(out)) {
                data.writeInt(value == null ? 0 : (Integer) value);
                return out.toByteArray();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public Object deserialize(byte[] bytes) {
            if (bytes == null || bytes.length == 0) return 0;
            try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(bytes))) {
                return in.readInt();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    private static final class LongSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            try (ByteArrayOutputStream out = new ByteArrayOutputStream();
                 DataOutputStream data = new DataOutputStream(out)) {
                data.writeLong(value == null ? 0L : (Long) value);
                return out.toByteArray();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public Object deserialize(byte[] bytes) {
            if (bytes == null || bytes.length == 0) return 0L;
            try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(bytes))) {
                return in.readLong();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    private static final class BooleanSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            return new byte[] {(byte) (((value != null) && ((Boolean) value)) ? 1 : 0)};
        }

        @Override
        public Object deserialize(byte[] bytes) {
            return bytes != null && bytes.length > 0 && bytes[0] != 0;
        }
    }

    private static final class DoubleSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            try (ByteArrayOutputStream out = new ByteArrayOutputStream();
                 DataOutputStream data = new DataOutputStream(out)) {
                data.writeDouble(value == null ? 0D : (Double) value);
                return out.toByteArray();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public Object deserialize(byte[] bytes) {
            if (bytes == null || bytes.length == 0) return 0D;
            try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(bytes))) {
                return in.readDouble();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    private static final class FloatSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            try (ByteArrayOutputStream out = new ByteArrayOutputStream();
                 DataOutputStream data = new DataOutputStream(out)) {
                data.writeFloat(value == null ? 0F : (Float) value);
                return out.toByteArray();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public Object deserialize(byte[] bytes) {
            if (bytes == null || bytes.length == 0) return 0F;
            try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(bytes))) {
                return in.readFloat();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    private static final class UuidSerializer implements PersistedBlobSerializer<Object> {
        @Override
        public byte[] serialize(Object value) {
            return value == null ? new byte[0] : value.toString().getBytes(StandardCharsets.UTF_8);
        }

        @Override
        public Object deserialize(byte[] bytes) {
            if (bytes == null || bytes.length == 0) return null;
            return UUID.fromString(new String(bytes, StandardCharsets.UTF_8));
        }
    }

    private static final class EnumSerializer implements PersistedBlobSerializer<Object> {

        private final Class<? extends Enum> enumType;

        private EnumSerializer(Class<? extends Enum> enumType) {
            this.enumType = enumType;
        }

        @Override
        public byte[] serialize(Object value) {
            return value == null ? new byte[0] : ((Enum<?>) value).name().getBytes(StandardCharsets.UTF_8);
        }

        @Override
        public Object deserialize(byte[] bytes) {
            if (bytes == null || bytes.length == 0) return null;
            return Enum.valueOf(this.enumType, new String(bytes, StandardCharsets.UTF_8));
        }
    }
}

