package fr.ibrakash.helper.persistence.entity.internal;

import fr.ibrakash.helper.persistence.entity.NoPersistedBlobSerializer;
import fr.ibrakash.helper.persistence.entity.PersistedBlobSerializer;
import fr.ibrakash.helper.persistence.entity.PersistedBlobSerializerRegistry;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;

class PersistedBlobSerializersRegistryTest {

    @Test
    void resolvesRegisteredGenericAndArraySerializers() throws Exception {
        Field listField = SampleFields.class.getDeclaredField("items");
        Field setField = SampleFields.class.getDeclaredField("itemSet");
        Field arrayField = SampleFields.class.getDeclaredField("itemArray");
        Field concreteListField = SampleFields.class.getDeclaredField("concreteItems");
        Field concreteSetField = SampleFields.class.getDeclaredField("concreteItemSet");

        var listType = PersistedBlobSerializerRegistry.parameterizedType(List.class, String.class);
        var setType = PersistedBlobSerializerRegistry.parameterizedType(Set.class, String.class);

        PersistedBlobSerializerRegistry.register(listType, StringListSerializer::new);
        PersistedBlobSerializerRegistry.register(setType, StringSetSerializer::new);
        PersistedBlobSerializerRegistry.register(String[].class, StringArraySerializer::new);

        try {
            PersistedBlobSerializer<Object> listSerializer = PersistedBlobSerializers.resolve(listField.getType(), listField.getGenericType(), NoPersistedBlobSerializer.class);
            PersistedBlobSerializer<Object> setSerializer = PersistedBlobSerializers.resolve(setField.getType(), setField.getGenericType(), NoPersistedBlobSerializer.class);
            PersistedBlobSerializer<Object> arraySerializer = PersistedBlobSerializers.resolve(arrayField.getType(), arrayField.getGenericType(), NoPersistedBlobSerializer.class);
            PersistedBlobSerializer<Object> concreteListSerializer = PersistedBlobSerializers.resolve(concreteListField.getType(), concreteListField.getGenericType(), NoPersistedBlobSerializer.class);
            PersistedBlobSerializer<Object> concreteSetSerializer = PersistedBlobSerializers.resolve(concreteSetField.getType(), concreteSetField.getGenericType(), NoPersistedBlobSerializer.class);

            assertNotNull(listSerializer);
            assertNotNull(setSerializer);
            assertNotNull(arraySerializer);
            assertNotNull(concreteListSerializer);
            assertNotNull(concreteSetSerializer);
            assertInstanceOf(StringListSerializer.class, listSerializer);
            assertInstanceOf(StringSetSerializer.class, setSerializer);
            assertInstanceOf(StringArraySerializer.class, arraySerializer);
            assertInstanceOf(StringListSerializer.class, concreteListSerializer);
            assertInstanceOf(StringSetSerializer.class, concreteSetSerializer);
        } finally {
            PersistedBlobSerializerRegistry.unregister(listType);
            PersistedBlobSerializerRegistry.unregister(setType);
            PersistedBlobSerializerRegistry.unregister(String[].class);
        }
    }

    @SuppressWarnings("unused")
    private static final class SampleFields {
        private List<String> items;
        private Set<String> itemSet;
        private String[] itemArray;
        private ArrayList<String> concreteItems;
        private LinkedHashSet<String> concreteItemSet;
    }

    private static final class StringListSerializer implements PersistedBlobSerializer<List<String>> {
        @Override
        public byte[] serialize(List<String> value) {
            return new byte[0];
        }

        @Override
        public List<String> deserialize(byte[] bytes) {
            return List.of();
        }
    }

    private static final class StringSetSerializer implements PersistedBlobSerializer<Set<String>> {
        @Override
        public byte[] serialize(Set<String> value) {
            return new byte[0];
        }

        @Override
        public Set<String> deserialize(byte[] bytes) {
            return Set.of();
        }
    }

    private static final class StringArraySerializer implements PersistedBlobSerializer<String[]> {
        @Override
        public byte[] serialize(String[] value) {
            return new byte[0];
        }

        @Override
        public String[] deserialize(byte[] bytes) {
            return new String[0];
        }
    }
}

