package fr.ibrakash.helper.persistence;

import com.mongodb.client.MongoDatabase;
import fr.ibrakash.helper.configuration.objects.database.ConfigPersistence;
import fr.ibrakash.helper.persistence.entity.internal.JsonEntityStore;
import fr.ibrakash.helper.persistence.entity.internal.SqlEntityStore;
import fr.ibrakash.helper.persistence.mongo.MongoPersistenceEngine;
import fr.ibrakash.helper.platform.KashAddon;
import fr.ibrakash.helper.sql.SqlDatabase;
import fr.ibrakash.helper.sql.SqlDriverType;
import fr.ibrakash.helper.sql.SqlResultStatement;
import fr.ibrakash.helper.sql.SqlStatement;

import java.io.File;
import java.sql.PreparedStatement;
import java.sql.Statement;

public class PersistenceSession implements AutoCloseable {

    private final PersistenceEngine engine;

    protected PersistenceSession(PersistenceEngine engine) {
        this.engine = engine;
    }

    protected PersistenceSession(KashAddon<?> addon, ConfigPersistence config) {
        this(PersistenceManager.create(addon, config));
    }

    public static PersistenceSession create(KashAddon<?> addon, ConfigPersistence config) {
        return new PersistenceSession(PersistenceManager.create(addon, config));
    }

    public <T, ID> EntityStore<T, ID> entity(Class<T> entityType, Class<ID> idType) {
        if (this.engine.type() == PersistenceType.SQL) {
            return new SqlEntityStore<>(this.engine, entityType, idType);
        }
        if (this.engine.type() == PersistenceType.JSON) {
            return new JsonEntityStore<>(this.engine, entityType, idType);
        }
        throw new UnsupportedOperationException("No generic EntityStore implementation for backend " + this.engine.type());
    }

    public PersistenceType backendType() {
        return this.engine.type();
    }

    // -------------------------------------------------------------------------
    // Direct backend access helpers
    // -------------------------------------------------------------------------

    public SqlDatabase sqlDatabase() {
        return this.engine.getSqlDatabase();
    }

    public SqlDriverType sqlDriver() {
        return this.engine.getDriverType();
    }

    public File storageFolder() {
        return this.engine.getStorageFolder();
    }

    public MongoDatabase mongoDatabase() {
        if (this.engine instanceof MongoPersistenceEngine mongo) {
            return mongo.getMongoDatabase();
        }
        throw new UnsupportedOperationException("mongoDatabase() is not available for backend " + this.engine.type());
    }

    // -------------------------------------------------------------------------
    // SQL shortcuts (no engine().getSqlDatabase() chain needed)
    // -------------------------------------------------------------------------

    public void execute(SqlStatement<Statement> consumer) {
        this.sqlDatabase().createClosingStatement(consumer);
    }

    public void prepare(String sql, SqlStatement<PreparedStatement> consumer) {
        this.sqlDatabase().prepareClosingStatement(sql, consumer);
    }

    public <V> V query(SqlResultStatement<Statement, V> consumer) {
        return this.sqlDatabase().resultStatement(consumer);
    }

    public <V> V query(String sql, SqlResultStatement<PreparedStatement, V> consumer) {
        return this.sqlDatabase().resultPreparedStatement(sql, consumer);
    }

    /** @deprecated Prefer direct helpers like {@link #sqlDatabase()} / {@link #query(String, SqlResultStatement)}. */
    @Deprecated(forRemoval = false)
    public PersistenceEngine engine() {
        return this.engine;
    }

    @Override
    public void close() {
        this.engine.close();
    }
}

package fr.ibrakash.helper.persistence;

import fr.ibrakash.helper.configuration.objects.database.ConfigPersistence;
import fr.ibrakash.helper.platform.KashAddon;
import fr.ibrakash.helper.sql.SqlDatabase;
import fr.ibrakash.helper.sql.SqlDriverType;
import fr.ibrakash.helper.sql.SqlResultStatement;
import fr.ibrakash.helper.sql.SqlStatement;

import java.io.File;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.util.EnumMap;
import java.util.Map;
import java.util.ServiceLoader;

public class PersistenceSession implements AutoCloseable {

    private static final Map<PersistenceType, EntityStoreFactory> STORE_FACTORIES = loadFactories();

    private final PersistenceEngine engine;

    protected PersistenceSession(PersistenceEngine engine) {
        this.engine = engine;
    }

    protected PersistenceSession(KashAddon<?> addon, ConfigPersistence config) {
        this(PersistenceManager.create(addon, config));
    }

    public static PersistenceSession create(KashAddon<?> addon, ConfigPersistence config) {
        return new PersistenceSession(PersistenceManager.create(addon, config));
    }

    public <T, ID> EntityStore<T, ID> entity(Class<T> entityType, Class<ID> idType) {
        EntityStoreFactory factory = STORE_FACTORIES.get(this.engine.type());
        if (factory == null) {
            throw new UnsupportedOperationException("No generic EntityStore implementation for backend " + this.engine.type());
        }
        return factory.create(this.engine, entityType, idType);
    }

    public PersistenceType backendType() {
        return this.engine.type();
    }

    // -------------------------------------------------------------------------
    // Direct backend access helpers
    // -------------------------------------------------------------------------

    public SqlDatabase sqlDatabase() {
        return this.engine.getSqlDatabase();
    }

    public SqlDriverType sqlDriver() {
        return this.engine.getDriverType();
    }

    public File storageFolder() {
        return this.engine.getStorageFolder();
    }

    // -------------------------------------------------------------------------
    // SQL shortcuts (no engine().getSqlDatabase() chain needed)
    // -------------------------------------------------------------------------

    public void execute(SqlStatement<Statement> consumer) {
        this.sqlDatabase().createClosingStatement(consumer);
    }

    public void prepare(String sql, SqlStatement<PreparedStatement> consumer) {
        this.sqlDatabase().prepareClosingStatement(sql, consumer);
    }

    public <V> V query(SqlResultStatement<Statement, V> consumer) {
        return this.sqlDatabase().resultStatement(consumer);
    }

    public <V> V query(String sql, SqlResultStatement<PreparedStatement, V> consumer) {
        return this.sqlDatabase().resultPreparedStatement(sql, consumer);
    }

    /** @deprecated Prefer direct helpers like {@link #sqlDatabase()} / {@link #query(String, SqlResultStatement)}. */
    @Deprecated(forRemoval = false)
    public PersistenceEngine engine() {
        return this.engine;
    }

    @Override
    public void close() {
        this.engine.close();
    }

    private static Map<PersistenceType, EntityStoreFactory> loadFactories() {
        EnumMap<PersistenceType, EntityStoreFactory> factories = new EnumMap<>(PersistenceType.class);
        ServiceLoader<EntityStoreFactory> loader = ServiceLoader.load(EntityStoreFactory.class);
        for (EntityStoreFactory factory : loader) {
            factories.putIfAbsent(factory.type(), factory);
        }
        return factories;
    }
}

package fr.ibrakash.helper.persistence.adapter;

import com.zaxxer.hikari.HikariDataSource;
import fr.ibrakash.helper.sql.SqlConsumer;
import fr.ibrakash.helper.sql.SqlDatabase;
import fr.ibrakash.helper.sql.SqlDriverType;
import fr.ibrakash.helper.sql.SqlResultStatement;
import fr.ibrakash.helper.sql.SqlStatement;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;

/**
 * Common SQL operation mixin for adapters.
 *
 * <p>Implementors only need to provide {@link #repository()}.
 */
public interface SqlAdapterOperations {

    DatabaseRepository repository();

    default SqlDatabase sqlDatabase() {
        return repository().sqlDatabase();
    }

    default SqlDriverType sqlDriver() {
        return repository().sqlDriver();
    }

    default ExecutorService sqlPool() {
        return sqlDatabase().getPool();
    }

    default HikariDataSource sqlDataSource() {
        return sqlDatabase().getDataSource();
    }

    default void openConnection(SqlConsumer<Connection> consumer) {
        sqlDatabase().openConnection(consumer);
    }

    default void execute(SqlStatement<Statement> consumer) {
        sqlDatabase().createClosingStatement(consumer);
    }

    default void prepare(String sql, SqlStatement<PreparedStatement> consumer) {
        sqlDatabase().prepareClosingStatement(sql, consumer);
    }

    default <V> V query(SqlResultStatement<Statement, V> consumer) {
        return sqlDatabase().resultStatement(consumer);
    }

    default <V> V query(String sql, SqlResultStatement<PreparedStatement, V> consumer) {
        return sqlDatabase().resultPreparedStatement(sql, consumer);
    }

    default void submitExecute(SqlStatement<Statement> consumer) {
        sqlDatabase().submitStatement(consumer);
    }

    default void submitPrepare(String sql, SqlStatement<PreparedStatement> consumer) {
        sqlDatabase().submitPreparedStatement(sql, consumer);
    }

    default <V> CompletableFuture<V> submitQuery(SqlResultStatement<Statement, V> consumer) {
        return sqlDatabase().submitResultStatement(consumer);
    }

    default <V> CompletableFuture<V> submitQuery(String sql, SqlResultStatement<PreparedStatement, V> consumer) {
        return sqlDatabase().submitPreparedResult(sql, consumer);
    }
}

