package fr.ibrakash.helper.persistence.entity;

public interface PersistedBlobSerializer<T> {

    byte[] serialize(T value);

    T deserialize(byte[] bytes);

    default T defaultValue() {
        return null;
    }
}

package fr.ibrakash.helper.persistence.entity;

import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.util.Arrays;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;

public final class PersistedBlobSerializerRegistry {

    private static final Map<Type, Supplier<? extends PersistedBlobSerializer<?>>> REGISTRY = new ConcurrentHashMap<>();

    private PersistedBlobSerializerRegistry() {
    }

    public static void register(Class<?> type, Supplier<? extends PersistedBlobSerializer<?>> factory) {
        register((Type) type, factory);
    }

    public static void register(Type type, Supplier<? extends PersistedBlobSerializer<?>> factory) {
        REGISTRY.put(Objects.requireNonNull(type, "type"), Objects.requireNonNull(factory, "factory"));
    }

    public static void unregister(Class<?> type) {
        unregister((Type) type);
    }

    public static void unregister(Type type) {
        REGISTRY.remove(type);
    }

    public static Type parameterizedType(Class<?> rawType, Type... actualTypeArguments) {
        return new SimpleParameterizedType(rawType, actualTypeArguments);
    }

    @SuppressWarnings("unchecked")
    public static PersistedBlobSerializer<Object> resolve(Type type) {
        Supplier<? extends PersistedBlobSerializer<?>> factory = REGISTRY.get(type);
        if (factory != null) {
            return (PersistedBlobSerializer<Object>) factory.get();
        }

        for (Map.Entry<Type, Supplier<? extends PersistedBlobSerializer<?>>> entry : REGISTRY.entrySet()) {
            if (matches(entry.getKey(), type)) {
                return (PersistedBlobSerializer<Object>) entry.getValue().get();
            }
        }

        return null;
    }

    private static boolean matches(Type registeredType, Type requestedType) {
        if (Objects.equals(registeredType, requestedType)) {
            return true;
        }
        if (!(registeredType instanceof ParameterizedType registered) || !(requestedType instanceof ParameterizedType requested)) {
            return false;
        }
        if (!Arrays.equals(registered.getActualTypeArguments(), requested.getActualTypeArguments())) {
            return false;
        }
        if (!(registered.getRawType() instanceof Class<?> registeredRaw) || !(requested.getRawType() instanceof Class<?> requestedRaw)) {
            return false;
        }
        return registeredRaw.isAssignableFrom(requestedRaw);
    }

    private static final class SimpleParameterizedType implements ParameterizedType {

        private final Class<?> rawType;
        private final Type[] actualTypeArguments;

        private SimpleParameterizedType(Class<?> rawType, Type[] actualTypeArguments) {
            this.rawType = Objects.requireNonNull(rawType, "rawType");
            this.actualTypeArguments = Objects.requireNonNull(actualTypeArguments, "actualTypeArguments").clone();
        }

        @Override
        public Type[] getActualTypeArguments() {
            return actualTypeArguments.clone();
        }

        @Override
        public Type getRawType() {
            return rawType;
        }

        @Override
        public Type getOwnerType() {
            return null;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof ParameterizedType other)) return false;
            return Objects.equals(rawType, other.getRawType())
                    && Objects.equals(getOwnerType(), other.getOwnerType())
                    && Arrays.equals(actualTypeArguments, other.getActualTypeArguments());
        }

        @Override
        public int hashCode() {
            return Arrays.hashCode(actualTypeArguments) ^ Objects.hashCode(rawType) ^ Objects.hashCode(getOwnerType());
        }

        @Override
        public String toString() {
            String args = Arrays.stream(actualTypeArguments)
                    .map(Type::getTypeName)
                    .reduce((left, right) -> left + ", " + right)
                    .orElse("");
            return rawType.getTypeName() + "<" + args + ">";
        }
    }
}

package fr.ibrakash.helper.paper.serialization.itemstack;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonSerializer;
import com.fasterxml.jackson.databind.SerializerProvider;
import org.bukkit.inventory.ItemStack;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Base64;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

public final class JsonItemStackSerializer {

    private JsonItemStackSerializer() {
    }

    private static String encode(byte[] bytes) {
        return Base64.getEncoder().encodeToString(bytes);
    }

    private static byte[] decode(String value) {
        if (value == null || value.isBlank()) {
            return new byte[0];
        }
        return Base64.getDecoder().decode(value);
    }

    public static class Serializer extends JsonSerializer<ItemStack> {
        @Override
        public void serialize(ItemStack value, JsonGenerator gen, SerializerProvider serializers) throws IOException {
            byte[] bytes = value == null ? new byte[0] : value.serializeAsBytes();
            gen.writeString(encode(bytes));
        }
    }

    public static class Deserializer extends JsonDeserializer<ItemStack> {
        @Override
        public ItemStack deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            byte[] bytes = decode(p.getValueAsString());
            if (bytes.length == 0) {
                return null;
            }
            return ItemStack.deserializeBytes(bytes);
        }
    }

    public static class ArraySerializer extends JsonSerializer<ItemStack[]> {
        @Override
        public void serialize(ItemStack[] value, JsonGenerator gen, SerializerProvider serializers) throws IOException {
            ItemStack[] items = value == null ? new ItemStack[0] : value;
            gen.writeString(encode(ItemStack.serializeItemsAsBytes(items)));
        }
    }

    public static class ArrayDeserializer extends JsonDeserializer<ItemStack[]> {
        @Override
        public ItemStack[] deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            byte[] bytes = decode(p.getValueAsString());
            if (bytes.length == 0) {
                return new ItemStack[0];
            }
            return ItemStack.deserializeItemsFromBytes(bytes);
        }
    }

    public static class ListSerializer extends JsonSerializer<List<ItemStack>> {
        @Override
        public void serialize(List<ItemStack> value, JsonGenerator gen, SerializerProvider serializers) throws IOException {
            ItemStack[] items = value == null || value.isEmpty() ? new ItemStack[0] : value.toArray(new ItemStack[0]);
            gen.writeString(encode(ItemStack.serializeItemsAsBytes(items)));
        }
    }

    public static class ListDeserializer extends JsonDeserializer<List<ItemStack>> {
        @Override
        public List<ItemStack> deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            byte[] bytes = decode(p.getValueAsString());
            if (bytes.length == 0) {
                return new ArrayList<>();
            }
            return new ArrayList<>(Arrays.asList(ItemStack.deserializeItemsFromBytes(bytes)));
        }
    }

    public static class SetSerializer extends JsonSerializer<Set<ItemStack>> {
        @Override
        public void serialize(Set<ItemStack> value, JsonGenerator gen, SerializerProvider serializers) throws IOException {
            ItemStack[] items = value == null || value.isEmpty() ? new ItemStack[0] : value.toArray(new ItemStack[0]);
            gen.writeString(encode(ItemStack.serializeItemsAsBytes(items)));
        }
    }

    public static class SetDeserializer extends JsonDeserializer<Set<ItemStack>> {
        @Override
        public Set<ItemStack> deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            byte[] bytes = decode(p.getValueAsString());
            if (bytes.length == 0) {
                return new LinkedHashSet<>();
            }
            return new LinkedHashSet<>(Arrays.asList(ItemStack.deserializeItemsFromBytes(bytes)));
        }
    }
}

